import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchBD: [CaseTemplate] = [windowFilmingNeighbor, firedWorkerTexts, hospitalBombCall, trailerToddlerNeglect, babysitterInfantInjury, poolMotherLeft, runawayRide, benefitCardCash, therapyBillingGhost, liftingBackClaim, stormRepairAdvance, sickPuppiesPapers, executorEstateSales, tuitionCheckBookkeeper, unionTreasurerChecks, campaignTreasurerCar, foodBankVacations, vendingRouteSkim, fireAuxTreasurer, washedChecks, scriptPadPrint, nursingDiplomaFake, twentiesCounterfeit, willForgeryHeir, barSkimmerPocket, loyaltyCardClones, electronicsCloneRing, deadWomanAccounts, loanForgivenessPhone, taxAgentGiftCards, wetlandsFillDump, muralPaintOver, fountainDestroyed, busSeatsSlashed, jailLockdownRiot, courthouseHallFight, ambulanceEntryBlock, paramedicCashTheft]

    static let windowFilmingNeighbor = SmallCases.make(
        key: "story.windowFilmingNeighbor",
        category: .violent,
        headlines: ["Neighbor Filmed Woman Through Windows and Followed Her to Work", "Camera Pole Found in Yard"],
        law: "stalking",
        threshold: 7,
        spec: "Willfully harassed {V} on more than one occasion without legitimate purpose, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "For two months {V} saw {D}, a neighbor, filming through windows and following {V.him} to work. A camera on a pole in {DL}'s yard faced {V}'s bedroom. {DL} says it was for security.",
        state: [E(.physical, 3, "Camera Pole", "A camera aimed at {V}'s windows.", .search), E(.video, 3, "Footage", "Hours of {V} inside the home."), E(.statement, 2, "Coworker", "{D} waited at the lot.")],
        defense: [E(.statement, 1, "Security", "{DL} says it was for security.")],
        role: "Coworker",
        exam: [.direct("What did you see at the parking lot where {V} works?", "\"I saw {D} waiting in a car at the lot most mornings, watching {V} arrive. It happened often enough that I noticed it.\""), .direct("What did {V} tell you about {D}?", "\"That {DL} had been filming through {V}'s windows and following {V.him} to work for about two months.\""), .direct("What did deputies find in the defendant's yard?", "\"A camera on a pole aimed at {V}'s windows. The footage shows hours of {V} inside the home.\""), .direct("How did {V} first come to you about this?", "\"{V} stopped by my desk in tears one morning and said {V.he} felt watched at home and on the drive in. I had noticed the same car behind {V} in the lot twice that month.\""), .direct("How do you know {V}?", "\"We work in the same office, two desks apart. I have known {V.him} for about three years, and I know where {V.he} parks every morning.\""), .direct("What did you do?", "\"I wrote down the plate and the time and gave the note to {V}. Later I told the deputies exactly what I had seen, with the dates.\""), .cross("{D} says the camera is for security, doesn't {D.he}?", "\"Yes. A camera on a pole can be for security. But this one was pointed at {V}'s windows.\""), .cross("Does the camera also cover the defendant's driveway?", "\"It covers part of the driveway, yes. That is true, and I will not deny it.\""), .cross("Did you personally see the defendant film anything?", "\"No. I saw {D.him} in the lot and heard from {V} about the filming. I did not watch the footage myself.\""), .cross("You never saw {D} take a picture or video, did you?", "\"No. I saw {DL} sitting and watching, and I cannot say what was on a phone or a camera.\""), .cross("Parking lots are public, aren't they?", "\"Our lot is for employees and visitors. {D.He} does not work for the company, which is why I took notice.\"")],
        defenseRole: "Neighbor across the road",
        defenseExam: [.direct("Does the camera on the pole face the street?", "\"Partly. It takes in the road and the front of the house, and some of the neighbors' yards.\""), .direct("Do you think it points at {V}'s windows?", "\"Maybe. It is hard to tell from where I live across the road. The angle is wide.\""), .direct("Have you seen {D} act strangely toward {V}?", "\"No. I have not seen {D} do anything threatening. I see a neighbor with a camera.\""), .direct("How well do you know the defendant?", "\"We live across the road from each other and talk over the fence now and then. {D.He} has helped me carry in groceries on more than one occasion.\""), .direct("What did you hear about the break-ins?", "\"Two sheds and a car on our road were hit, and neighbors were all uneasy. Several people put up cameras that winter.\""), .direct("What did you see about the camera?", "\"It sits on a pole near {D.his} mailbox and points down the road. From my porch it looks like it faces the street.\""), .cross("Did you see the footage that was recorded?", "\"No. I did not see it. I only know where the camera points from the road.\""), .cross("Does the camera see into the windows of {V}'s home?", "\"It might. I cannot tell for certain, and I would not want to say it does not.\""), .cross("Have you been told that the defendant was asked to stop?", "\"I heard something about a written notice.\""), .cross("You have never looked at the camera's footage, have you?", "\"No. I do not know what is on it, and I did not ask to see it.\""), .cross("You cannot say where the lens points exactly from your porch, can you?", "\"Not exactly, no. I know it looks toward the road, but a pole angle can change.\"")],
        theory: ("{D} stalked a neighbor.", "Security."),
        allocution: "\"I crossed a line, and I understand that now. I put up that camera because I'd had break-ins, and I wanted a good view of my yard and driveway. I never meant to record {V}. I'm sorry for the fear it caused, and I'll take the camera down and keep my distance.\"",
        truths: ("{DL} had been told in writing to stop.", "The camera also covers {DL}'s own driveway."),
        defendant: [.direct("Did you film {V} through the windows?", "\"No, I did not. The camera is for security. It watches my property, and I never meant to record {V.him}.\""), .direct("Why did you put a camera on a pole?", "\"For security. I had problems with break-ins, and a pole gave me a good view of my yard and driveway.\""), .direct("Were you told to stop by {V}?", "\"Yes, I got a written notice. I took it seriously, but I believed the camera was legal.\""), .direct("What were the break-ins you mentioned?", "\"Two sheds on our road had been hit over the winter, and a car stereo was stolen from my own driveway. I bought a camera and mounted it on a pole to cover the road.\""), .direct("Where did you aim it?", "\"Down the road toward the corner and across the driveway. I set it on a wide lens, and I did not think about the house across the way.\""), .direct("How did you react to the written notice?", "\"I felt accused, and I was annoyed because I thought I was only protecting my property. I did not move the camera, and I now see that was a mistake.\""), .cross("The camera has {V}'s windows in frame, doesn't it?", "\"Yes. They are in the frame. I did not aim it there on purpose, but I did not fix it either.\""), .cross("You waited at the parking lot where {V} works, didn't you?", "\"I was there some mornings. It was a coincidence. I use that road for my own errands.\""), .cross("You got a written warning and kept the camera up, didn't you?", "\"I should have moved it. I did not think I was doing anything wrong.\""), .cross("The footage had hours of {V}'s home on it, didn't it?", "\"I have been told it did. I did not watch it closely, and I do not know how much was inside the windows.\""), .cross("You were seen at {V}'s work more than once, weren't you?", "\"I was in that lot a few times because a friend works nearby. I did not follow anyone there.\"")],
        openings: ("For two months, {V} saw {D}, a neighbor, filming through windows and waiting at {V}'s work lot. A camera on a pole in {DL}'s yard was aimed at {V}'s bedroom windows, and {DL} had been warned in writing.", "Listen for the defense evidence, which will show that the camera was installed for security, also covers {D}'s own driveway, and that no one has shown {DL} meant to spy on anyone."),
        closings: ("A camera aimed at {V}'s windows, hours of footage inside the home, a coworker who saw {D} waiting at the lot, and a written warning that was ignored. This is stalking.", "A security camera on a pole that sees the street, a driveway, and a neighbor's window by accident. The State must prove {D} aimed it to harass, and it has not."),
        timeline: [(-60, "The pole goes up."), (0, "Month 2: the lot."), (0, "Month 2: the footage is found."), (1, "{DL} is arrested.")],
        identified: "A camera pole.",
        mood: .wantsConviction,
        impact: "I stopped opening my curtains, even on sunny days. For two months I saw that man outside my windows with a phone, and a camera on a pole faced my bedroom. I started leaving for work earlier and checking my mirrors the whole way. I want my own house to feel like mine again.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let firedWorkerTexts = SmallCases.make(
        key: "story.firedWorkerTexts",
        category: .violent,
        headlines: ["Fired Worker Sends Threatening Texts to Former Boss", "Messages Mention the Boss's Children"],
        law: "communicatingThreats",
        threshold: 7,
        spec: "Communicated a threat to {V} to cause fear, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After being fired, {D} sent {V}, a former boss, 22 texts on {DATE} saying {V.he} would 'pay' and mentioning {V.his} children's school. {DL} says it was venting. {DL} was fired the day before. The 22 texts came at about 8 p.m., and {V} called deputies an hour later after {V}'s spouse locked the doors.",
        state: [E(.digital, 3, "Text Messages", "22 threatening messages."), E(.document, 2, "Termination Letter", "Fired the day before."), E(.statement, 2, "Spouse", "{V} locked the doors.")],
        defense: [E(.statement, 1, "Venting", "{DL} says it was venting.")],
        role: "Former boss",
        exam: [.direct("What happened the evening after {DL} was fired?", "\"At about 8 p.m. I received 22 texts from {D}, saying I would 'pay' and mentioning my children's school. {D.He} had been fired the day before.\""), .direct("How did you react to the messages?", "\"I was frightened. My spouse locked the doors, and about an hour later I called deputies. I didn't know what {D.he} might do.\""), .direct("What did the messages say about your children?", "\"They mentioned the school by name. That was what scared me most. It told me {DL} knew where my children were every day.\""), .direct("What was {D}'s role before the firing?", "\"A line supervisor on my shift for about four years. The firing came after a safety violation and two warnings.\""), .direct("What did the texts say, in substance?", "\"That I would pay, that I had ruined a life, and that {D.he} knew where my children's school was. They came in a stream, one right after another, between eight and nine.\""), .direct("What did you do after reading them?", "\"I showed my spouse, who locked the doors and turned on the porch light. I called the sheriff's office about an hour later and read them the messages.\""), .cross("{DL} says it was venting, doesn't {D.he}?", "\"I know {D.he} was angry about being let go. But venting doesn't usually name a child's school.\""), .cross("Had {DL} ever been violent at work?", "\"No. In all the time {DL} worked for me, {DL} was never violent. That's part of why this was so unsettling.\""), .cross("Did {DL} come to your home?", "\"Not that night, as far as I know. The messages were the threat. Nobody came to the door.\""), .cross("{D} never showed up at your home, did {D.he}?", "\"Not that night. A deputy drove by and saw nothing out of place.\""), .cross("You received an apology the next morning, didn't you?", "\"Yes, a short text from {D.him}. It did not settle my nerves, because of the school mention.\"")],
        defenseRole: "Coworker",
        defenseExam: [.direct("Do you know {DL} from work?", "\"Yes. I worked alongside {D} for years. I saw {DF} the day the firing happened.\""), .direct("How was {DL} that day?", "\"Very angry. {D.He} felt humiliated and said some harsh things, but mostly about the job.\""), .direct("Was {DL} ever physical with anyone?", "\"No. {DF} yells sometimes, but I've never seen {DF} lay a hand on anyone.\""), .direct("What did you see the day of the firing?", "\"{D.He} came out of the office red-faced and gathered a box of belongings. I walked {D.him} to the gate, and we talked about nothing for a minute.\""), .direct("What did {D} say to you that night?", "\"A short call, mostly venting about the injustice. I told {D.him} to go to bed and not do anything stupid.\""), .direct("How has the defendant behaved at work over the years?", "\"Steady, a little hot-tempered with equipment but never with people. {D.He} covered shifts for others when asked.\""), .cross("Did {DL} say anything about {V}'s family?", "\"Not to me. I only heard anger about the firing. Nothing about children.\""), .cross("Did you see the texts?", "\"No. I only heard about them afterward. I can't speak to what was in them.\""), .cross("Were you worried about {DL}?", "\"A little, because {DF} was so upset. Not that {DF} would hurt anyone, but that {DF} would say something rash.\""), .cross("You did not hear about the school, did you?", "\"No. I only learned about that from the deputies.\""), .cross("You cannot say what was in the defendant's mind when typing, can you?", "\"No. I only know {DF} was hurt and angry, and I have never seen {DF} act on it.\"")],
        theory: ("{D} threatened a boss.", "Venting."),
        allocution: "\"I was furious and hurt about being fired, and I sent things I never meant. I knew where {V}'s children went to school because we'd talked about it at work, and mentioning it was cruel. I regret every word of those texts. I never planned to hurt anyone, and I'm sorry.\"",
        truths: ("{DL} drove past the school once.", "{DL} apologized to {V} by text the next morning."),
        defendant: [.direct("Why did you send those texts?", "\"I was furious and hurt about being fired. I was venting, and I wrote things I didn't mean. I never planned to hurt anyone.\""), .direct("Why did you mention the school?", "\"I knew where {V}'s children went because we'd talked about it at work. I mentioned it in anger. It was cruel, and I regret it.\""), .direct("Did you intend to harm {V}?", "\"No. I wanted {V.him} to feel bad about firing me. I'd never touch a child. I was out of my head with anger.\""), .direct("How were you feeling that evening?", "\"Humiliated and scared about money. I was driven home by a coworker and sat in the dark with a bottle of beer.\""), .direct("What were you thinking while you typed?", "\"Mostly that I wanted {V.him} to feel what I felt. I did not plan any act, but I was out of control with anger.\""), .direct("What did you do the next morning?", "\"I woke up sick about what I had sent and wrote an apology. I knew it was too late to take it back.\""), .cross("22 texts in a short time isn't venting, is it?", "\"It was a flood, I know. I kept typing. I'm ashamed of how many I sent.\""), .cross("You said {V} would 'pay,' didn't you?", "\"Yes. I meant {V} would regret it, not that I would harm anyone. I see how it reads.\""), .cross("You brought up {V}'s children, didn't you?", "\"Yes. That was the worst thing I wrote. I wish I could take it back.\""), .cross("You drove past the school once, didn't you?", "\"Yes. I was driving aimlessly and ended up on that street. I did not stop or get out.\""), .cross("You chose to mention the children, didn't you?", "\"I did, and it was the cruelest thing I wrote. I regret that more than anything.\"")],
        openings: ("The day after being fired, {D} sent {V}, a former boss, 22 texts promising {V} would 'pay' and naming {V.his} children's school. {V}'s spouse locked the doors, and deputies were called an hour later. The State will show the texts.", "The defense evidence includes an angry employee who had just lost a job, who vented in words and nothing more, and who had never been violent."),
        closings: ("Twenty-two texts in one evening, a promise that {V} would pay, and a mention of the children's school. {V}'s family locked their doors in fear.", "A fired worker's anger poured out in texts, with no visit, no weapon, and no history of violence. The State has not proved {D} meant it as a true threat."),
        timeline: [(-1, "{DL} is fired."), (0, "8 p.m.: the texts."), (0, "9 p.m.: {V} calls deputies."), (1, "{DL} is arrested.")],
        identified: "Text messages.",
        aggravating: ["The offense involved a threat"],
        mood: .divided,
        impact: "We changed our routine overnight. I drove the kids to school myself, we locked the doors at dusk, and I stopped answering unknown numbers. Twenty-two texts came in one evening, and one mentioned where my children go to school. It's hard to explain that kind of fear to a child.",
        doctrines: ["relevance"])

    static let hospitalBombCall = SmallCases.make(
        key: "story.hospitalBombCall",
        category: .violent,
        headlines: ["Caller Claims Bomb at Hospital, Forcing Evacuation", "Phone Traced to a Prepaid Line"],
        law: "massViolenceThreat",
        threshold: 8,
        spec: "Threatened to commit mass violence at a hospital, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "A caller said on {DATE} a bomb was in a hospital and forced a three-hour evacuation of 200 patients. The prepaid phone was traced to {D}, a former patient. {DL} says the phone was stolen.",
        state: [E(.digital, 3, "Call Record", "A prepaid phone used for the call."), E(.video, 3, "Store Camera", "{D} buys the phone."), E(.statement, 2, "Dispatcher", "A male voice.")],
        defense: [E(.statement, 1, "Stolen", "{DL} says the phone was stolen.")],
        role: "911 dispatcher",
        exam: [.direct("What call did you take on {DATE}?", "\"A caller said a bomb was in the hospital. I stayed on the line as long as I could and sent it up immediately.\""), .direct("What was the result?", "\"A three-hour evacuation of 200 patients. Nurses moved people who were hooked to machines, and it was frightening for everyone.\""), .direct("What was the voice like?", "\"A deep voice, calm and deliberate. I couldn't tell you a name. It sounded like an adult.\""), .direct("How long did the call last?", "\"About three minutes. I stayed on the line and kept the caller talking while a coworker alerted security.\""), .direct("What did you do?", "\"I kept the caller on as long as I could and asked questions, but the line went dead within a minute. I alerted the hospital security and the sheriff's office at once.\""), .direct("How was the evacuation carried out?", "\"Staff moved all 200 patients out in stages, including some on oxygen and a few on ventilators. The bomb squad searched the building for three hours before the all clear.\""), .cross("Can you say whose voice it was?", "\"No. I have no way to identify the voice. I only know what I heard on the recording.\""), .cross("Did the caller say why?", "\"No reason was given. The caller said there was a bomb and hung up.\""), .cross("Was a bomb found?", "\"No. The building was searched and nothing was found. That's why the question is who called.\""), .cross("The call was from a prepaid phone, wasn't it?", "\"Yes, a prepaid phone with no registration. The record showed it hitting a tower near the hospital.\""), .cross("You did not hear any background sounds you can identify, did you?", "\"A little road noise and what might have been a television. Nothing I could tie to a place.\"")],
        defenseRole: "Phone store clerk",
        defenseExam: [.direct("Do you remember {DL} at your store?", "\"Yes. {D} bought a prepaid phone from us. We have the sale record.\""), .direct("How did the purchase go?", "\"Ordinary. {D.He} paid, took the phone, and left. Nothing unusual.\""), .direct("Has {DL} been in before?", "\"A couple of times. {DF} is a regular customer. Always polite.\""), .direct("What kind of phones do you sell?", "\"Prepaid phones and plans, mostly for people who do not want a contract. We sell dozens a week.\""), .direct("What do you remember about {D}?", "\"A polite customer, early afternoon, paid cash for a basic model and a card of minutes. We have a camera at the counter.\""), .direct("What does your system record?", "\"The sale time, phone number, and card of minutes sold. We do not keep ID for those sales.\""), .cross("When did {DL} buy it?", "\"Weeks earlier than the call. I don't have the exact date in my head.\""), .cross("Did you sell any other phones that day?", "\"Yes, many. I can't say who else bought a prepaid phone.\""), .cross("Do you know who had it later?", "\"No. I only know who bought it. I have no knowledge of what happened afterward.\""), .cross("You cannot say what the defendant did with the phone, can you?", "\"No. Once it leaves the counter, I have no idea who has it.\""), .cross("Other people may have bought phones the same week, right?", "\"Yes, many people. I only recall {DF} because of the camera footage the deputy showed me.\"")],
        theory: ("{D} called in a bomb.", "A stolen phone."),
        allocution: "\"I'm so sorry for the patients and staff who went through that evacuation. I did not make that call. I was a patient in that hospital once, and I'd never do anything to endanger sick people. The phone was stolen from me before that day, and I'm asking the court to remember that.\"",
        truths: ("{DL} had a billing dispute with the hospital.", "{DL} reported the phone stolen a day later."),
        defendant: [.direct("Did you call the hospital?", "\"No. I did not make that call. I'm a former patient, and I'd never endanger people in a hospital.\""), .direct("How do you explain the phone being traced to you?", "\"The phone was stolen. I'd bought it, but someone took it. I didn't have it when the call was made.\""), .direct("Why did you buy a prepaid phone?", "\"For ordinary use. It was cheaper than a contract. I used it for a few weeks before it went missing.\""), .direct("What was your history with the hospital?", "\"I was a patient there last year, and there was a dispute over a bill. I was still angry about it.\""), .direct("When did you lose the phone?", "\"A few weeks after I bought it, I noticed it missing from my bag at a laundromat. I assumed I had dropped it.\""), .direct("When did you report it stolen?", "\"The day after the call, when deputies came to my door and told me it had been used. I reported it then.\""), .cross("The store camera shows you buying that phone, doesn't it?", "\"Yes. I bought it. I'm not denying that. But I didn't have it that day.\""), .cross("The call came from that phone, didn't it?", "\"That's what they say. Someone else must have had it.\""), .cross("You were a patient at that hospital, weren't you?", "\"Yes, once. That doesn't mean I'd threaten it. It's where I was treated.\""), .cross("You were angry at that hospital, weren't you?", "\"Angry about the bill, yes. That is far from calling in a bomb.\""), .cross("You did not report the loss before the call, did you?", "\"No. I did not think of it as a theft until the deputies showed up.\"")],
        openings: ("A caller told 911 a bomb was in a hospital, forcing a three-hour evacuation of 200 patients. The prepaid phone used for the call was bought on camera by {D}, a former patient. The State will present the dispatcher and the records.", "The defense will point you to a phone that was stolen weeks after purchase, a store clerk who confirms the timing, and no voice that anyone can match to {D}."),
        closings: ("A bomb threat, 200 patients evacuated, and a prepaid phone that {D} bought on camera. The phone is tied to {D.him} by the store's own video.", "Buying a phone is not making a call. {D} says it was stolen, and no one can identify the voice. The State has not proved who spoke."),
        timeline: [(-1, "The billing dispute."), (0, "2 p.m.: the call."), (0, "2:10 p.m.: evacuation."), (1, "{DL} is traced.")],
        identified: "A phone record.",
        aggravating: ["The offense involved a threat"],
        mood: .wantsConviction,
        impact: "Our patients were frightened, and we had to move two hundred of them out in three hours. Some were on oxygen, some on dialysis, and one had just come out of surgery. We pushed beds into the parking lot. I'll never forget their faces looking up at us.",
        doctrines: ["burdenOfProof"])

    static let trailerToddlerNeglect = SmallCases.make(
        key: "story.trailerToddlerNeglect",
        category: .family,
        headlines: ["Parents Leave Toddler in Trailer Without Food for Days", "Neighbor Hears Crying"],
        law: "felonyChildAbuse",
        threshold: 8,
        spec: "Intentionally inflicted serious bodily injury on {V}, a child, by omission, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A neighbor heard a toddler crying for days and called deputies on {DATE}. {V}, two, was found dehydrated with an empty fridge. {D}, the mother, had been away. {DL} says a relative was supposed to watch {V.him}.",
        state: [E(.statement, 3, "Neighbor", "'The crying lasted three days.'"), E(.forensic, 3, "Medical Report", "Dehydration."), E(.physical, 2, "Home", "An empty refrigerator.", .search)],
        defense: [E(.statement, 1, "Relative", "{DL} says a relative was watching {V.him}.")],
        role: "Neighbor",
        exam: [.direct("What did you hear from the trailer next door?", "\"A toddler crying for days. It went on for about three days, and I finally called deputies.\""), .direct("What did deputies find when they went in?", "\"{V}, age two, dehydrated and weak, in a home with an empty refrigerator.\""), .direct("Where was {D}?", "\"Away. {D} was gone for about four days, and no one seemed to be checking on the child.\""), .direct("How close do you live to the defendant?", "\"Next door, sharing a fence. Our trailers are about twenty feet apart, and the walls are thin.\""), .direct("What did the crying sound like?", "\"At first it was regular, like any toddler. By the second day it was hoarse and weak, and by the third it was a thin steady wail with long pauses.\""), .direct("What did you do?", "\"I knocked on the door twice and got no answer, then called the sheriff's office. A deputy and I stood on the step while they forced the lock.\""), .cross("{D} says a relative was supposed to watch {V}, doesn't {D.he}?", "\"That is what I understand. I did not see a relative come or go at any time.\""), .cross("Did you ever see the defendant caring for {V} before?", "\"Yes, sometimes. I saw {DL} with the child on other days. It was not always like this.\""), .cross("How far is your trailer from the defendant's?", "\"Close. We share a fence. That is how I could hear the crying so clearly.\""), .cross("You did not see anyone going in or out, did you?", "\"Not after the first morning. I saw {D.him} leave with a duffel and a coat, and nobody came by.\""), .cross("You did not call earlier than the third day, did you?", "\"No. I told myself it was a normal toddler tantrum, and I regret that.\"")],
        defenseRole: "Relative",
        defenseExam: [.direct("Were you asked to watch {V} while {D} was away?", "\"Yes. {D} asked me to look after {V} for a few days, and I said I would do it.\""), .direct("Did you watch {V} as agreed?", "\"I started to. Then I got sick and could not leave my bed. I should have called someone.\""), .direct("Did you tell the defendant you were sick?", "\"I sent a text saying I would come Thursday. I was hoping I would be better by then.\""), .direct("How are you related to the defendant?", "\"I am a close family member. I live twenty minutes from the trailer and have helped with the child before.\""), .direct("What did you agree to do?", "\"To stay at the trailer from Monday and look after the toddler for three days. I said yes without hesitating.\""), .direct("What happened to you?", "\"I came down with the flu Sunday night, with a high fever and vomiting. I could not stand up for two days.\""), .cross("Did you check on {V} at all during those days?", "\"No. I did not go over. I was very sick, and I did not think about calling anyone else.\""), .cross("Did you tell anyone {V} was alone?", "\"No. I did not tell the neighbors or deputies. I wish I had.\""), .cross("Did the defendant call you while away to check on things?", "\"Once, I think. I said all was fine, and I regret that.\""), .cross("You did not call anyone else to cover for you, did you?", "\"No. I thought I would feel better by Thursday and did not want to worry {DF}.\""), .cross("Your text said you would come Thursday, didn't it?", "\"Yes, and that was well after the child needed care. I now understand how serious that gap was.\"")],
        theory: ("{D} left a toddler.", "A relative."),
        allocution: "\"I failed {V.him}. I trusted a relative to look after my little one while I worked out of town for four days, and I should have checked in more. I never meant for {V.him} to be hungry or alone. I love {V.him}, and I'll do whatever it takes to earn {V.him} back.\"",
        truths: ("{DL} was away for four days.", "The relative's text says she would come Thursday."),
        defendant: [.direct("Why did you leave {V} alone?", "\"I did not think I was leaving {V.him} alone. I trusted a relative to look after {V.him} while I worked.\""), .direct("Where were you for those days?", "\"Working, out of town. I had a job that kept me away for about four days.\""), .direct("Did you check in on {V} while you were gone?", "\"Once. I called and was told everything was fine. I should have pushed harder for an answer.\""), .direct("Why were you away?", "\"I took a short-term job in another town paying cash, and I needed it to cover rent. I planned to be gone three days and ended up four.\""), .direct("What arrangements did you make for care?", "\"I asked a relative to stay at the trailer and watch the child. I left money for food and diapers on the counter.\""), .direct("What did you do when you got home?", "\"I found deputies and an ambulance. I rode with {V.him} to the hospital and stayed all night.\""), .cross("You were gone four days with a two-year-old at home, weren't you?", "\"Yes. I relied on a relative. It was a bad plan, and I know that.\""), .cross("You only checked in once in four days, didn't you?", "\"Yes. I should have called more. I was working long hours and told myself it was fine.\""), .cross("You did not confirm that the relative had actually arrived, did you?", "\"I texted and was told I would be seen Thursday. I took that to mean it was fine.\""), .cross("The refrigerator was empty, wasn't it?", "\"Yes. I left money and assumed the relative would buy food, and I did not stock it myself.\""), .cross("You never called anyone to check on {V} while you were away, did you?", "\"I called the relative once and got no answer. I should have called again, and I should not have left {V} without making sure someone came.\"")],
        openings: ("A neighbor heard a toddler crying for three days and called deputies. They found {V}, age two, dehydrated in a home with an empty refrigerator, while {D} had been away for four days.", "Jurors will hear that {D} arranged for a relative to watch {V}, that the relative fell ill, and that {DL} never meant to abandon the child."),
        closings: ("Three days of crying, a dehydrated toddler, an empty refrigerator, and a parent who was away for four days. A child that young cannot take care of anything alone.", "A parent who arranged for a relative to watch {V.him}, a relative who got sick, and a plan that failed. The State must prove culpable neglect, not bad luck."),
        timeline: [(0, "Day 1: the mother leaves."), (0, "Day 3: the neighbor calls."), (0, "Day 4: deputies enter."), (0, "Day 4: {V} is hospitalized.")],
        identified: "A neighbor.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .sympathetic,
        impact: "{V.He} is in foster care now, and I visit {V.him} on Saturdays for an hour. {V.He}'s a good child, and {V.he} cried for days in that trailer. I don't know yet whether I can bring {V.him} home. I want {V.him} to feel safe and fed and loved, wherever that is.",
        doctrines: ["lesserIncluded"],
        genders: ["D": .female, "V": .male])

    static let babysitterInfantInjury = SmallCases.make(
        key: "story.babysitterInfantInjury",
        category: .family,
        headlines: ["Babysitter Charged After Infant Suffers Skull Fracture", "Parents Return to Fussy Baby"],
        law: "felonyChildAbuse",
        threshold: 8,
        spec: "Intentionally inflicted serious physical injury on {V}, a child under 16, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Parents returned on {DATE} to find {V}, a four-month-old, fussy and swollen. A scan showed a skull fracture. {D}, the babysitter, was alone with {V.him}. {DL} says {V.he} fell from a couch.",
        state: [E(.forensic, 3, "Medical Report", "Skull fracture inconsistent with a short fall."), E(.statement, 3, "Parent", "'{V} was fine when we left.'"), E(.digital, 2, "Text", "{D} texts 'baby was fussy.'")],
        defense: [E(.statement, 1, "Couch", "{DL} says {V} fell from a couch.")],
        role: "Pediatrician",
        exam: [.direct("What did you find when you examined {V}?", "\"A skull fracture on a four-month-old who was fussy and swollen. The scan showed it clearly.\""), .direct("Is the fracture consistent with a short fall?", "\"No. In my medical opinion, this kind of fracture is inconsistent with a short fall from a couch.\""), .direct("What were you told about the history?", "\"The parents said {V} was fine when they left. {D}, the babysitter, was alone with {V} and texted that the baby was fussy.\""), .direct("How was {V} when brought to you?", "\"Irritable and fussy, with a soft swollen area on the right side of the head. {V} was feeding poorly and vomited once in the exam room.\""), .direct("What imaging was done?", "\"A head CT, which showed a linear skull fracture on the right parietal bone with a small area of swelling beneath. There was no bleeding inside the skull.\""), .direct("What does a fracture like that usually come from?", "\"A significant force, such as a fall from a height of several feet onto a hard surface or a direct blow. It is less often the result of a short fall onto carpet.\""), .cross("{DL} says {V} fell from a couch, doesn't {D.he}?", "\"A short fall can cause injuries in infants, but a skull fracture like this is unusual.\""), .cross("Could you rule out a fall completely?", "\"I can't say it's impossible. I can say it's very unlikely given the nature of the injury.\""), .cross("Were there other injuries?", "\"None that I documented beyond the swelling and the fracture. I didn't find other signs of abuse.\""), .cross("A short fall can cause a fracture in an infant, can't it?", "\"It can, though it is uncommon. The couch being eighteen inches high and the floor being carpet makes it less likely.\""), .cross("You did not witness any event, did you?", "\"No. I only know what was told to me and what I saw in the scans.\"")],
        defenseRole: "Second pediatrician",
        defenseExam: [.direct("Do you review pediatric head injuries?", "\"Yes. I'm a pediatrician and I see these cases. I reviewed the records here.\""), .direct("Could a fall cause a fracture like this?", "\"Rarely, but it can happen. Infants' skulls are thin, and bad luck on a hard floor can do it.\""), .direct("Have you seen it from short falls?", "\"Yes, occasionally. It's not common, but it's documented.\""), .direct("What is your area of practice?", "\"General pediatrics, with a special interest in head injuries in young children. I have reviewed many scans of infants over the years.\""), .direct("What did you review in this case?", "\"The CT images, the chart, and the history. I did not examine {V} myself.\""), .direct("How common is that in your own practice?", "\"In a small number of cases over many years. It's rare, but I've seen it and the literature supports it.\""), .cross("From a couch, is it likely?", "\"Unlikely. I wouldn't call it likely at all. It would take unusual circumstances.\""), .cross("Did you examine {V}?", "\"No. I reviewed the records and images only. I can't speak to the exam findings.\""), .cross("Could an inflicted injury look the same?", "\"It could. That's why history matters. I can't tell from the images alone.\""), .cross("Most such falls cause no fracture at all, don't they?", "\"Yes. That is why this fracture draws attention, and I would not call it typical.\""), .cross("The history provided is a key piece, isn't it?", "\"Absolutely. If the history does not match the injury, that raises concern.\"")],
        theory: ("{D} hurt an infant.", "A fall."),
        allocution: "\"{V} rolled off the couch while I was in the room, and I heard a thump and picked {V.him} up right away. {V.He} was fussy and I told the parents, and I didn't see a bump at first. I would never hurt a baby, and I'm heartbroken about what {V.he} has been through.\"",
        truths: ("{DL} waited three hours to call.", "The couch is eighteen inches high."),
        defendant: [.direct("What happened while you were watching {V}?", "\"{V} was on the couch and rolled off. I heard a thump and picked {V.him} up. {V.he} was crying and fussy.\""), .direct("What did you do?", "\"I comforted {V.him} and texted the parents that the baby was fussy. I didn't see any bump at first.\""), .direct("Did you hurt {V}?", "\"No. I would never hurt a baby. I loved caring for {V.him}. It was an accident, and I'm so sorry.\""), .direct("How long had you been watching {V}?", "\"I arrived at one when the parents left and watched {V} for six hours. I fed {V.him}, changed {V.him}, and put {V.him} on a blanket on the couch.\""), .direct("What exactly did you see?", "\"I stepped to the kitchen for a bottle, and I heard a thump. {V} was on the floor, and I picked {V.him} up right away.\""), .direct("Why did you wait to call?", "\"{V} cried for a minute and then settled, and I thought it was minor. I watched for signs and checked {V.him} every few minutes.\""), .cross("You didn't tell the parents about a fall, did you?", "\"I told them {V} was fussy. I didn't think the fall was serious, and I should have said more.\""), .cross("The doctors say a short fall doesn't cause that fracture, don't they?", "\"That's what they say. I can only tell you what I saw. {V} fell off the couch.\""), .cross("You were alone with {V}, weren't you?", "\"Yes. The parents were out. I was the only one there.\""), .cross("You waited about three hours before telling anyone, didn't you?", "\"I texted the parents that the baby was fussy. I did not mention the fall, and I have regretted that every day.\""), .cross("The couch is eighteen inches high, isn't it?", "\"Yes, about that. I know that is not high, and I do not know how else to explain it.\"")],
        openings: ("Parents came home to find {V}, a four-month-old, fussy and swollen, and a scan showed a skull fracture. {D}, the babysitter, was alone with {V}. The State will present the pediatrician and the medical report.", "Jurors will also see a second pediatrician who says a short fall can occasionally cause this fracture, and a babysitter who texted the parents as soon as {V} was fussy."),
        closings: ("A four-month-old with a skull fracture that doctors say a couch fall does not explain, and only one person was with {V}. The injury was not an accident.", "Doctors agree a short fall is rare but possible. {D} was alone with a baby who fell, and told the parents. The State has not proved {DL} caused the injury."),
        timeline: [(0, "1 p.m.: parents leave."), (0, "4 p.m.: the fall, {DL} says."), (0, "7 p.m.: parents return."), (0, "9 p.m.: the scan.")],
        identified: "A medical report.",
        aggravating: ["The victim was particularly vulnerable", "The defendant took advantage of a position of trust or confidence"],
        mood: .wantsConviction,
        impact: "Our baby will need care for life, and the doctors can't say yet how much. We left {V.him} for a few hours to attend a family event. When we came back, {V.he} was swollen and fussy, and a scan showed a fractured skull. We spend our nights listening to {V.him} breathe.",
        doctrines: ["expertTestimony"])

    static let poolMotherLeft = SmallCases.make(
        key: "story.poolMotherLeft",
        category: .family,
        headlines: ["Mother Leaves Two Children Alone at Public Pool", "Lifeguard Finds Boy in Deep End"],
        law: "childAbuseMisd",
        threshold: 6,
        spec: "Committed child abuse by negligent supervision of {V}, a minor, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A lifeguard pulled {V}, six, from a deep end on {DATE} while {D} was gone for an hour. {V} recovered. {DL} says {D.he} left only briefly.",
        state: [E(.statement, 3, "Lifeguard", "'No adult was with them.'"), E(.video, 2, "Pool Camera", "{D} leaves at 1:10."), E(.forensic, 2, "Medical Note", "Water inhaled; recovered.")],
        defense: [E(.statement, 1, "Brief", "{DL} says {D.he} left only briefly.")],
        role: "Lifeguard",
        exam: [.direct("What happened at the pool at 1:10 p.m.?", "\"{D} left the pool area at about 1:10 and did not come back for an hour. Meanwhile, a six-year-old was in the deep end.\""), .direct("What did you do?", "\"I saw {V} in trouble in the deep end and pulled {V.him} out. No adult was with the children.\""), .direct("What condition was {V} in?", "\"{V} had inhaled water but recovered. A medical note records it.\""), .direct("Where were you stationed that afternoon?", "\"In the chair at the deep end, facing the lap lanes. It was a busy summer afternoon with about forty people in the water.\""), .direct("How did you notice {V}?", "\"I saw a small child slip under near the rope line and not come back up. I jumped in, brought {V.him} up, and got {V.him} onto the deck.\""), .direct("What did {V} look like?", "\"Coughing hard, with water running out of the nose and mouth. Another lifeguard called for an ambulance while I checked {V.his} breathing.\""), .cross("Was an older child watching {V}?", "\"An older child was around. I was told the older child had agreed to watch {V.him}.\""), .cross("Did {V} recover fully?", "\"Yes. {V} recovered. I was relieved and so was everyone else.\""), .cross("Did you see {D} leave?", "\"Yes, at 1:10. The camera shows it too.\""), .cross("An older child was at the pool, wasn't there?", "\"Yes, a child around eleven was sitting at the edge reading a book. I do not recall seeing that child watching {V}.\""), .cross("The adult was gone long before the incident, wasn't the defendant?", "\"Yes, since 1:10 by the camera. I did not see {D.him} again until 2:20.\"")],
        defenseRole: "Older sibling",
        defenseExam: [.direct("Did your parent ask you to watch {V}?", "\"Yes. My parent said to keep an eye on {V} while stepping away for a bit. I said okay.\""), .direct("How old were you that day?", "\"Eleven. I was the oldest child at the pool, and I felt responsible for watching my younger sibling.\""), .direct("Did you watch {V} the whole time?", "\"No. I looked away for a while to talk to a friend. When I looked back, the lifeguard was already helping.\""), .direct("What did your parent tell you before leaving?", "\"To watch {V} and not let {V.him} go in the deep end. I said okay and promised.\""), .direct("What happened while you were watching?", "\"I was talking with a friend near the snack stand, and I looked up and {V} was gone from the shallow end. Then I saw the lifeguard jump.\""), .direct("How did you feel?", "\"Terrified. I thought I had killed my sibling, and I ran toward the deck.\""), .cross("Did you tell your parent you looked away?", "\"Not right away. I was scared and ashamed. I told my parent later.\""), .cross("How long were you not watching?", "\"Maybe a few minutes. It felt short to me, but I know it was enough.\""), .cross("Did your parent say where the trip was going?", "\"A store, I think. I did not know it was a bar.\""), .cross("You were not watching when {V} slipped under, were you?", "\"No. I was looking the other way.\""), .cross("You are only eleven, aren't you?", "\"Yes. I now know that is too young to be in charge of a small child at a pool.\"")],
        theory: ("{D} left children alone.", "Briefly away."),
        allocution: "\"I stepped away to the store next door for a few things, and I thought it would be quick. I asked my older child to watch my younger one, and I shouldn't have. I'm thankful the lifeguard was there, and I'll never leave a child near water again.\"",
        truths: ("{DL} went to a bar next door.", "The older child was eleven and agreed to watch."),
        defendant: [.direct("Did you leave the children at the pool?", "\"Briefly. I stepped away for a short while, and I asked my older child to watch the younger one.\""), .direct("Where did you go?", "\"To a store next door. I needed a few things and thought it would be quick.\""), .direct("Why did you leave the pool?", "\"I told myself I would be fifteen minutes at most. I stepped out to buy cigarettes and ended up at the bar next door.\""), .direct("What did you do at the bar?", "\"I had a drink with a friend and lost track of time. I did not look at a clock until a text from the pool arrived.\""), .direct("How did you feel when you got back?", "\"Sick to my stomach. {V} was on a stretcher, and the lifeguard said what had happened.\""), .direct("What did you tell the older child before you left?", "\"To keep an eye on the little one and stay out of the deep end. I thought I would be back in a few minutes.\""), .cross("You were gone for an hour, weren't you?", "\"It may have been. I lost track of time. I know that is no excuse.\""), .cross("You left a six-year-old near a deep end with an eleven-year-old watching, didn't you?", "\"Yes. I trusted my older child. I should not have put that on someone so young.\""), .cross("The child inhaled water. Do you understand how serious that is?", "\"Yes. I am so grateful {V} recovered.\""), .cross("You did not tell the lifeguard you were leaving, did you?", "\"No, I did not say a word to the lifeguard. I just walked out, and I should have asked someone to keep an eye on them.\""), .cross("An eleven-year-old cannot rescue a six-year-old in deep water, can they?", "\"No, probably not. I understand that now. I trusted the older child too much, and I will carry that for the rest of my life.\"")],
        openings: ("A lifeguard pulled {V}, age six, from the deep end of a pool while {D} had been gone for an hour. The pool camera shows {DL} leaving at 1:10, and the lifeguard says no adult was with the children.", "By the end of this trial, the proof will show that {D} left the children in the care of an eleven-year-old and meant to be gone only briefly."),
        closings: ("A six-year-old in the deep end, an hour-long absence, and a parent at a bar next door. Only the lifeguard's quick action prevented a tragedy.", "A short errand, an older child who agreed to watch, and a lifeguard who stepped in. {V} recovered, and the State cannot prove {D} meant any harm."),
        timeline: [(0, "1:10 p.m.: {DL} leaves."), (0, "2 p.m.: the boy slips."), (0, "2:05 p.m.: rescue."), (0, "2:20 p.m.: {DL} returns.")],
        identified: "A pool camera.",
        mood: .sympathetic,
        impact: "I won't swim again, not after that day at the deep end. I remember going under and not being able to find the bottom. The lifeguard got me out, and my mother wasn't there. I still wake up gasping, and my family has had to learn to be careful with me.",
        doctrines: ["lesserIncluded"],
        genders: ["D": .female])

    static let runawayRide = SmallCases.make(
