        defense: [E(.statement, 1, "Age", "{DL} says {V} claimed eighteen.")],
        role: "Detective",
        exam: [.direct("What did you find in the texts between {D} and {V}?", "\"The messages show {D} and {V} planning a drive out of state. {V} had run away from home.\""), .direct("What does the toll camera show?", "\"{D.his} car crossing the state line. It shows the date and time of the crossing.\""), .direct("What did {V}'s parent tell you?", "\"That {V} is fifteen. The parent reported {V} missing, and we found {V} out of state with {DL}.\""), .direct("How did the case come to you?", "\"{V}'s parent called the sheriff's office at midnight when {V} did not come home from school. A search of {V}'s phone gave us the name of the person {V} had been texting.\""), .direct("What do the texts show?", "\"Over about ten days {DL} and {V} discussed leaving town, and {DL} agreed to drive {V} to another state on a Friday. They talk about the route and a meeting place.\""), .direct("What did you do to find them?", "\"I pulled the toll records and found {D.his} plate crossing the state line that night. Local deputies in the next county located {V} at a motel the next morning.\""), .cross("{D} says {V} said {V.he} was eighteen, doesn't {D.he}?", "\"Yes. {DL} says that. There is a message where {V} says eighteen.\""), .cross("What age did {V}'s profile show?", "\"It listed fifteen. {DL} may have missed that.\""), .cross("Did {D} try to hide the trip?", "\"No. {D.He} drove openly across the state line, and the toll camera caught the car.\""), .cross("{V} left home willingly, didn't {V.he}?", "\"Yes. {V} packed a bag, and the texts show {V} proposing the trip. That does not change the legal age.\""), .cross("The message where {V} claims to be eighteen is in the texts, isn't it?", "\"Yes, one message states it. The profile page for the same account lists fifteen.\"")],
        defenseRole: "Friend of {V}",
        defenseExam: [.direct("What age did {V} tell you?", "\"Eighteen. {V} said that to me more than once, and I believed it.\""), .direct("Did {V} say that to {D} as well?", "\"Yes, from what I saw. {V} told people eighteen, and I think {D} believed it too.\""), .direct("Why did {V} run away?", "\"{V} said things at home were bad. {V} wanted to leave and asked for a ride.\""), .direct("How do you know {V}?", "\"We are close friends and we sit together at school. {V} told me about the trip but made me promise not to tell.\""), .direct("What did {V} say about age?", "\"{V} said at school that everyone thinks I look older and told me that online everyone thinks eighteen. I knew that was not true.\""), .direct("What did you do after {V} left?", "\"I texted a few times and got short replies. I was scared and finally told a teacher the next day.\""), .cross("Did you ever see {V}'s age listed anywhere?", "\"I saw the profile later. It said fifteen. I did not look at it before.\""), .cross("Did you know {V} was a minor?", "\"No. I thought {V} was eighteen. I would not have helped otherwise.\""), .cross("Did you tell anyone {V} was going out of state?", "\"No. I did not. I know I should have.\""), .cross("You knew {V} was fifteen, didn't you?", "\"Yes, because we are classmates. I do not know what {V} told {DF}.\""), .cross("You did not tell {V}'s parent right away, did you?", "\"No. I was afraid of getting {V} in trouble, and I wish I had called at once.\"")],
        theory: ("{D} took a minor across state lines.", "A mistaken age."),
        allocution: "\"{V} asked me for help leaving a bad situation, and I drove {V.him} because I believed {V.he} was eighteen. {V.He} told me so in a message and I took {V.him} at {V.his} word. I should have asked for more proof. I regret all the worry I caused {V.his} family.\"",
