        defendant: [.direct("Did you drive {V} out of state?", "\"Yes, I did. I drove {V} because {V.he} asked for help leaving a bad situation.\""), .direct("How old did you think {V} was?", "\"Eighteen. {V} told me so in a message, and I took {V.him} at {V.his} word.\""), .direct("Did you see the profile listing fifteen?", "\"I missed it. I did not look closely at the profile, and I wish I had.\""), .direct("How did you meet {V}?", "\"Through an online group about music. We chatted for a few weeks, and {V} said things at home were rough.\""), .direct("What did {V} say about age?", "\"In a message {V} said eighteen and that a birthday was coming up. I had no reason to doubt it, since {V} sounded mature.\""), .direct("What happened during the drive?", "\"About four hours in the car, talking and playing music. I dropped {V} at a motel near a friend's place and went to work.\""), .cross("{V}'s parent says {V} is fifteen. Why did you not check?", "\"In hindsight, yes. I believed what {V} said, and I did not ask for proof.\""), .cross("You planned the trip by text, didn't you?", "\"Yes. We talked about it. I thought I was helping someone who needed to get away.\""), .cross("You crossed a state line with a minor, didn't you?", "\"I did, but I did not know {V.he} was a minor. I truly am sorry.\""), .cross("You never asked for any ID, did you?", "\"No. I took the word of someone I had been talking with, and I regret not asking.\""), .cross("You did not tell anyone you were taking {V} out of state, did you?", "\"No. I did not, because I thought it was a private matter between two adults.\"")],
        openings: ("{V}, a fifteen-year-old runaway, was driven out of state by {D} after the two planned the trip by text. A toll camera caught {DL}'s car crossing the state line, and {V}'s parent says {V} is fifteen.", "The defense will present evidence that {V} told {D}, in writing, and told others too, that {V.he} was eighteen, and that {DL} believed it and meant to help."),
        closings: ("Texts that planned the drive, a toll camera, and a profile that listed fifteen. {D} took a child across a state line without asking a single question.", "{V} told {D} eighteen in a message, and {DL} took that at face value. The State must prove {DL} knew {V} was a minor, and the messages say otherwise."),
        timeline: [(-7, "{V} runs away."), (0, "The drive."), (1, "The parent reports."), (2, "{DL} is arrested.")],
