        state: [E(.document, 3, "Altered Checks", "Ink bled; amounts rewritten."), E(.video, 3, "Bank Camera", "{D} cashes a check."), E(.physical, 2, "Solvent Kit", "Acetone and pens in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Handed", "{DL} says a friend handed {D.him} the checks.")],
        role: "Bank teller",
        exam: [.direct("What did you notice about the checks that came to your window?", "\"The ink had bled and the amounts looked rewritten. The checks had been washed in solvent and rewritten for much larger sums.\""), .direct("How did you recognize {D}?", "\"From bank camera video of {D} cashing a check at my window. I recognized {D.him} when {D.he} came in again.\""), .direct("What was found in the defendant's car?", "\"Acetone and pens. A solvent kit like that is what is used to wash a check and write a new amount.\""), .direct("What do you do at the bank?", "\"I am a teller at the main branch and handle check cashing and deposits. I see dozens of checks a day.\""), .direct("What was strange about the checks?", "\"The paper felt slightly rough where the amounts were written, and the blue ink had faint ghosting around the numbers. The amount line said $1,800 over a smeared area.\""), .direct("What happened after you flagged them?", "\"I held the checks and called a supervisor, who contacted the issuing business. They said the original amount was $180.\""), .cross("{D} says the checks were handed to {D.him} to cash, doesn't {D.he}?", "\"Yes, that is what {DL} told us. A friend gave {DL} the checks and asked for a favor.\""), .cross("Did the defendant hide {D.his} identity at the window?", "\"No. {D.He} used a real ID and stood in front of the camera. I will say that.\""), .cross("Acetone is common, isn't it?", "\"Yes. It is found in nail polish remover and many households. It is not unusual to have it.\""), .cross("{D} was polite and calm, wasn't {D.he}?", "\"Yes. {D.He} showed ID and filled out the endorsement without hesitation.\""), .cross("Many customers present checks that are not theirs, don't they?", "\"It happens. A friend or family member may ask someone to cash a check, and we ask about it.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("Did you hand {D} any checks to cash?", "\"Yes. I gave {D} some checks and asked {D.him} to cash them for me as a favor.\""), .direct("Did you know the checks had been altered?", "\"No. I had no idea. They looked normal to me, and I did not examine the amounts closely.\""), .direct("How do you know the defendant?", "\"We have been friends for years and live a few blocks apart. We text almost daily.\""), .direct("Where did you get the checks?", "\"From a person at a meeting who offered me a cut if I could cash them. I did not have an account at the bank.\""), .direct("What did you tell the defendant?", "\"That they were good and from a landscaping business. I did not know they had been changed.\""), .direct("Why did you ask the defendant for help with the checks?", "\"{DF} has helped me with errands before, and cashing a check seemed like a small favor between friends. I never thought it could cause trouble.\""), .cross("Did you pay the defendant for cashing them?", "\"I gave {DF} a fee for the favor. It was $200, as I recall, and I do not think that was unusual.\""), .cross("Did you tell the defendant where the checks came from?", "\"No. I did not explain. I should have, and I know that does not help {D.him}.\""), .cross("Is your name in the defendant's phone?", "\"Yes. We know each other, and we have texted before. I am not hiding that.\""), .cross("You paid the defendant to cash them, didn't you?", "\"Yes, $200 for the job.\""), .cross("You handed the defendant a stack of checks in envelopes, didn't you?", "\"Yes, I handed over a stack in a few envelopes at {DF}'s door. I did not look through them with {D.him}.\"")],
        theory: ("{D} cashed altered checks.", "A friend's handoff."),
        allocution: "\"I never washed or rewrote a check. I cashed checks a friend handed me as a favor, and he offered me two hundred dollars for it. I should have asked where they came from. I regret my part, and I'll help in any way I can.\"",
        truths: ("{DL} had acetone in the car.", "The friend's name is in {DL}'s phone."),
        defendant: [.direct("Did you alter those checks?", "\"No. I never washed or rewrote a check. I cashed checks that a friend handed me as a favor.\""), .direct("Why did you agree to cash them?", "\"As a favor to a friend, who offered me a $200 fee. I did not question where they came from.\""), .direct("What was the acetone in your car for?", "\"Nail polish. I keep a bottle in the car for my own nails, and the pens are ordinary pens.\""), .direct("How did you come to cash the checks?", "\"A friend asked me to cash a handful because the friend had no bank account. I agreed to do it for a fee.\""), .direct("What were you told about the checks?", "\"That they were payments from a landscaping job and were good. I had no reason to doubt that.\""), .direct("What did you do after the teller flagged them?", "\"I stayed at the window and answered questions. I gave the name of my friend and offered my phone.\""), .cross("The ink on those checks bled where the amounts were rewritten. Did you not see that?", "\"I did not look closely. The checks looked fine to me, and I trusted my friend.\""), .cross("You took a $200 fee for walking checks into a bank, didn't you?", "\"I did. That was a lot for a favor. I should have wondered why.\""), .cross("You had acetone and pens in your car. Is that a coincidence?", "\"I realize how that sounds. They were for my own use, and I did not use them on checks.\""), .cross("You were paid $200 to cash them, weren't you?", "\"Yes. I should have asked why a friend would pay that much for a simple errand.\""), .cross("You never looked at the ink or the amounts, did you?", "\"I did not. They looked like ordinary checks to me.\"")],
        openings: ("Mail was stolen, and checks were washed in solvent and rewritten for larger sums. A bank teller recognized {D} from video cashing one, and a solvent kit with acetone and pens was found in {D.his} car.", "Jurors will hear that a friend handed {D} the checks to cash as a favor, that {DL} used a real ID, and that acetone is an ordinary household item."),
        closings: ("Bled ink, rewritten amounts, a camera at the teller window, and a solvent kit in {D}'s car. The checks were altered, and {DL} cashed them.", "A friend gave {D} checks, and {DL} cashed them under {D.his} own name with a real ID. The State must prove {DL} knew they were altered."),
        timeline: [(-14, "Mail is stolen."), (0, "10 a.m.: the check is cashed."), (1, "The payee notices."), (3, "{DL} is arrested.")],
        identified: "A bank camera.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "Bills bounced for two weeks. I put a check in the mail for the rent and the electric, and it came out of my account for a much bigger amount. I had to borrow from my sister to cover groceries. It took months to get the bank to put my money back.",
        doctrines: ["mistakeOfFact"],
        genders: ["D": .male])

    static let scriptPadPrint = SmallCases.make(
        key: "story.scriptPadPrint",
