        defense: [E(.statement, 1, "Friend", "{DL} says a friend printed them.")],
        role: "Pharmacist",
        exam: [.direct("What did you notice about the prescriptions?", "\"They came on pads printed from a doctor's template that had been stolen. The format matched the real pads, but the doctor never wrote them.\""), .direct("What does the pharmacy camera show?", "\"{D} at four different pharmacy counters, filling prescriptions. {D.He} was arrested after the fourth.\""), .direct("What was found in {D}'s home?", "\"A printer with the template saved on it. It was in the home {DL} shares with a friend.\""), .direct("How did you spot the first prescription?", "\"It was for a strong opioid in a quantity larger than the doctor usually writes. The prescription pad looked right, but the doctor's DEA number was off by a digit.\""), .direct("How did you confirm it was forged?", "\"I called the doctor's office, and the staff said no prescription for that patient had been issued. They sent over the real pad for comparison.\""), .direct("What happened after that?", "\"Pharmacists across the county were alerted. Three other pharmacies reported scripts from the same pad, filled by the same person.\""), .cross("{D} says a friend printed them, doesn't {D.he}?", "\"Yes. {DL} says a friend who lives there printed the pads. The friend has not been charged.\""), .cross("Who owns the printer?", "\"I understand it is shared by {DL} and the friend. I do not know who bought it.\""), .cross("Did {D} try to hide at the counters?", "\"No. {DL} came in the open and used a real name. The camera shows {DL} each time.\""), .cross("The person in the video used a real ID, didn't {D.he}?", "\"Yes, a state ID in {D.his} own name. That is how we identified {D.him} so quickly.\""), .cross("You did not see who printed the pads, did you?", "\"No. I only saw the pads and the person who brought them in.\"")],
        defenseRole: "Roommate",
        defenseExam: [.direct("Who owns the printer in the home?", "\"Both of us. We bought it together when we moved in, and we both use it for whatever we need.\""), .direct("Who uses the printer most often?", "\"{D} sometimes does, but I use it too. I do not keep track of what each of us prints.\""), .direct("Did you ever see the doctor's template on it?", "\"No. I never looked at what was stored on it. I did not know there was anything like that.\""), .direct("What is your connection to {D}?", "\"We are roommates and have lived together for two years. We share most of the household equipment.\""), .direct("Who uses the printer most?", "\"We both do. It's on a shelf in the living room, and anyone in the house can reach it.\""), .direct("Did you see anything on it?", "\"Once I noticed a stack of blank pad-style paper next to it. I did not think about it.\""), .cross("Did you print any prescriptions?", "\"No. I did not print them. I do not know who did, and I am not going to guess.\""), .cross("Could the defendant have printed them without you knowing?", "\"Yes. I am out a lot, and the printer is in the common area. It would be easy to do.\""), .cross("Are you friends with the defendant?", "\"We live together. I am telling you what I know, but I know that is not enough.\""), .cross("You do not know who printed on it that week, do you?", "\"I was at work most days. I cannot say who was home.\""), .cross("You never checked what was stored on it, did you?", "\"No. I never opened the files, and I do not know what was there.\"")],
        theory: ("{D} used forged scripts.", "A friend."),
        allocution: "\"I did not print those prescriptions, and a friend gave them to me. I brought them to the pharmacies as a favor because I believed they were real. I'm sorry for my part in this, and for the doctor whose name is on them.\"",
        truths: ("The printer was in {DL}'s home.", "The friend lives there too."),
        defendant: [.direct("Did you print the prescriptions?", "\"No. I did not print them. A friend printed them, and I did not know they were stolen.\""), .direct("Did you fill the four prescriptions?", "\"Yes, I did. I brought them to the pharmacies as a favor, and I believed they were real.\""), .direct("Whose printer was it?", "\"Shared. A roommate and I share it, and the roommate prints things for work and for other people.\""), .direct("How did you get the prescriptions?", "\"A friend I share a home with gave me four and asked me to pick up the medicine. I took them to different pharmacies because one was closed.\""), .direct("What did you think they were for?", "\"I thought they were for my friend's chronic back pain. I did not think to question them.\""), .direct("What did you do when the pharmacist called a deputy?", "\"I stayed, handed over the paper, and answered questions. I gave the deputy my friend's name.\""), .cross("You went to four different pharmacies with the same kind of prescription, didn't you?", "\"Yes. It seemed fine. I did not think about it until the fourth.\""), .cross("The printer with the doctor's template was in your home, wasn't it?", "\"Yes. But it is shared, and I did not use that template.\""), .cross("You never asked where the prescriptions came from?", "\"I did not ask enough. I trusted my friend.\""), .cross("You carried four prescriptions to four pharmacies, didn't you?", "\"Yes. It seemed convenient at the time, and now it looks suspicious.\""), .cross("Does your friend have access to your computer?", "\"Yes, the same shared one in the living room. I never locked it.\"")],
        openings: ("Pharmacies received prescriptions on pads printed from a stolen doctor's template. A pharmacy camera shows {D} at four counters, and a printer with the template was found in {D.his} home.", "The defense evidence will establish that a roommate printed the pads on a shared printer, and that {D} filled them believing they were real."),
        closings: ("Four pharmacy counters, four forged prescriptions, and a printer with the doctor's template in {D}'s own home. {DL} presented every one of them.", "A shared printer, a roommate who printed, and a person who carried papers to a pharmacy and believed they were real. The State must prove {D} knew."),
        timeline: [(-30, "The template is stolen."), (0, "Week 1: store one."), (0, "Week 3: store four."), (1, "{DL} is arrested.")],
        identified: "A pharmacy camera.",
        mood: .wantsConviction,
        impact: "My name was on those pads. Someone took my template and printed prescriptions I never wrote, and the pharmacies filled them. I've spent my career earning that trust. Now every patient and pharmacist has to wonder whether a script from me is real.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let nursingDiplomaFake = SmallCases.make(
