        state: [E(.document, 3, "Diploma", "Diploma with a bad seal."), E(.document, 3, "Registrar Letter", "No record."), E(.statement, 2, "Charge Nurse", "Skills did not match.")],
        defense: [E(.statement, 1, "Lost Records", "{DL} says the school lost records.")],
        role: "Hospital HR director",
        exam: [.direct("What did {D} present to your hospital?", "\"A nursing diploma. It had a bad seal that looked like a printed copy rather than an embossed seal.\""), .direct("What did the school's registrar tell you?", "\"That the school had no record of {D}. The registrar sent a letter saying no one by that name graduated.\""), .direct("How long did the defendant work at the hospital?", "\"Six weeks. The charge nurse noticed that {DL}'s skills did not match what a graduate nurse should be able to do.\""), .direct("How did the defendant come to your attention?", "\"The charge nurse on the unit told me {DL} was struggling with basic tasks like starting an IV and calculating doses. The nurse asked to see {DL}'s credentials.\""), .direct("What did you do?", "\"I pulled the file and sent the diploma to the school for verification. Two days later the registrar answered that there was no record of {DL}.\""), .direct("What was wrong with the diploma?", "\"The embossed seal was a flat printed copy, not raised, and the paper stock was thinner than the school's real diplomas. A comparison sample made it clear.\""), .cross("{D} says the school lost its records, doesn't {D.he}?", "\"Yes. That is what {D.he} said. The school did go through a merger, and records may have moved.\""), .cross("Could a merger explain the missing record?", "\"It could explain some missing records. It would not explain a printed seal.\""), .cross("Did the defendant treat any patient badly?", "\"I am not aware of a specific harm. The concern was about skills, and the charge nurse caught it.\""), .cross("The school did go through a merger, didn't it?", "\"Yes, three years ago, with another school. Some older records were transferred and some were not.\""), .cross("No patient complained, did they?", "\"None that I am aware of. The concern came from the nurses who worked beside {D.him}.\"")],
        defenseRole: "Former classmate",
        defenseExam: [.direct("Did {D} attend the nursing program with you?", "\"I think so. I remember {D} in some of our classes, though it was a big program.\""), .direct("Do you know whether the defendant graduated?", "\"I am unsure. I did not keep track of who finished and who did not.\""), .direct("What do you remember about the defendant's skills?", "\"{D.He} was a little rusty, like many of us were after a gap, but {D.he} seemed to know the basics.\""), .direct("How do you know the defendant?", "\"We attended the same program at the same time, and we shared a few labs. We lost touch after graduation.\""), .direct("What do you recall about the defendant?", "\"A quiet student who studied hard and sometimes asked for help with clinical skills. {D.He} passed the same exams I did, as far as I remember.\""), .direct("What do you know about the school?", "\"It merged with a larger college a few years back. I have heard some old transcripts could not be found.\""), .cross("Do you remember the defendant at graduation?", "\"No. I do not remember seeing {DF} at the ceremony. It was a crowded event.\""), .cross("Did you see the defendant's diploma?", "\"No. I never saw it.\""), .cross("Are you close to the defendant?", "\"We were classmates. I am friendly with {D.him}, but I am not sure about the facts.\""), .cross("You do not remember seeing the defendant's diploma, do you?", "\"No, I never saw it.\""), .cross("How many students were at the ceremony?", "\"Hundreds. The families and graduates filled the gym, and I couldn't pick out any one person.\"")],
        theory: ("{D} forged a diploma.", "Lost records."),
        allocution: "\"I'm sorry for the worry this has caused the hospital and the patients I looked after. I did not forge that diploma. The one I gave them is the one the school gave me. I was told the school merged with another and records were lost. I worked hard and I cared for people.\"",
        truths: ("The seal is a printed copy.", "The school moved records in a merger."),
        defendant: [.direct("Did you forge that diploma?", "\"No. I did not forge it. The diploma I gave the hospital is the one the school gave me.\""), .direct("Why does the school have no record?", "\"The school merged with another one, and records got lost. That is what I was told.\""), .direct("What about the seal on the diploma?", "\"It looks odd to me, too. I never studied it. I assumed it was normal.\""), .direct("Where did you earn your degree?", "\"At a nursing program in another state, which I finished eight years ago. I was a licensed nurse there for about two years.\""), .direct("How did you get the diploma?", "\"The school mailed it to me after graduation, and I kept it framed in my home. I brought the frame to the interview.\""), .direct("What did you do after leaving nursing?", "\"I took a long break to care for family and worked in other fields. When I came back, I was rusty.\""), .cross("The seal is a printed copy, isn't it?", "\"I do not know. That is what they say. I did not make it.\""), .cross("Your skills did not match a graduate's, did they?", "\"I was rusty after a long break. I was nervous, and I made mistakes.\""), .cross("You worked six weeks as a nurse with no verified degree, didn't you?", "\"I did. I believed I had one. I am sorry for the trouble.\""), .cross("You did not tell the hospital that your school had merged, did you?", "\"No, I did not know about the merger when I applied. I only learned about it when the registrar's office had no record of me.\""), .cross("You did not request a transcript from the school before applying, did you?", "\"No. I assumed my diploma would be enough.\"")],
        openings: ("{D} presented a nursing diploma to a hospital and worked six weeks as a nurse. The school's registrar has no record of {DL}, the diploma has a printed seal, and the charge nurse saw that the skills did not match.", "By the end of this trial, the proof will show that the school merged with another and lost records, that classmates recall {D} attending, and that {D.he} believed the diploma was real."),
        closings: ("A diploma with a printed seal, no record at the school, and a nurse whose skills did not match the paper. Patients depended on {D}'s word.", "A school that merged and lost records, and a classmate who remembers {D}. The State must prove {DL} knew the diploma was false."),
        timeline: [(-42, "The application."), (0, "The hire."), (42, "The registrar replies."), (43, "{DL} is suspended.")],
        identified: "A diploma.",
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let twentiesCounterfeit = SmallCases.make(
        key: "story.twentiesCounterfeit",
        category: .whiteCollar,
        headlines: ["Man Passed Counterfeit Twenties in Five Towns", "Bills Share a Serial Number"],
