        defense: [E(.statement, 1, "Change", "{DL} says the bills were change.")],
        role: "Store clerk",
        exam: [.direct("What did you notice about the twenty-dollar bill?", "\"It was counterfeit. The same serial number showed up on bills in five towns, which is how we knew.\""), .direct("What do the store cameras show?", "\"It shows {D} passing bills at three stores. We captured {D.him} at our counter too.\""), .direct("What was found in {D}'s possession?", "\"A printer and paper were found when deputies searched. The printer is a color printer.\""), .direct("How did you spot the bill?", "\"The pen mark did not react, and the paper felt too smooth. I also noticed the serial number matched one in an alert sheet from the police.\""), .direct("What does the alert sheet say?", "\"That twenty-dollar bills with the same serial were turning up across five towns. Our store clerk network shared the number.\""), .direct("What did you do?", "\"I held the bill, wrote down the time and a description, and called the sheriff's office. We pulled the camera footage that afternoon.\""), .cross("{D} says the bills came as change, doesn't {D.he}?", "\"Yes. That is what {D.he} told us. {D.He} said a bar gave the change.\""), .cross("Do clerks ever receive counterfeit bills by mistake?", "\"Yes. It happens often. Many people pass them without knowing.\""), .cross("Did {D} try to hide when passing the bills?", "\"No. {DL} passed them in the open and did not seem nervous.\""), .cross("Counterfeit bills are often passed unknowingly, aren't they?", "\"Yes, they pass through many hands. I cannot say anyone knew.\""), .cross("{D} paid openly at the counter, didn't {D.he}?", "\"Yes, with no hurry. {D.He} bought a few small items and walked out.\"")],
        defenseRole: "Coworker",
        defenseExam: [.direct("Did {D} tell you about receiving change?", "\"Yes. {D} said that {D.he} got change in twenties at a bar the night before.\""), .direct("Which bar was that?", "\"A bar in town. {D.He} mentioned the name, but I cannot recall exactly which one it was.\""), .direct("Did the defendant seem to know the bills were bad?", "\"No. {D.He} seemed surprised when deputies told {D.him}. {D.He} did not act guilty to me.\""), .direct("How do you know the defendant?", "\"We work together on the same crew and spend most of the day together. We ride to jobs in the same truck.\""), .direct("What did the defendant tell you about the bills?", "\"That a bar had given a handful of twenties in change. {D.He} did not seem to think about it.\""), .direct("Where did the defendant work that week?", "\"Across three of those towns on different days. The route is part of our regular jobs.\""), .cross("Did you see the defendant receive the change?", "\"No. I was not with {D.him} that night.\""), .cross("Does the defendant own a printer?", "\"Yes. A color printer. Many people do, and I have one too.\""), .cross("Did the defendant travel to different towns?", "\"Yes. {D.He} travels for work, and I think that is why the bills turned up in many places.\""), .cross("Can anyone tell which printer produced the forms?", "\"I'm not aware of any test that can, and I wouldn't claim one could.\""), .cross("You did not watch the defendant receive the change at the bar, did you?", "\"No. I was at a different table. I only know what {D.he} told me and what the receipt later showed.\"")],
        theory: ("{D} passed fake bills.", "Change."),
