        defense: [E(.statement, 1, "Signed", "{DL} says {V} signed it.")],
        role: "Estate attorney",
        exam: [.direct("What did {D} present after {V} died?", "\"A will leaving the farm to {D}. It was witnessed by two friends of {DL}.\""), .direct("What did the handwriting expert find?", "\"The signature on the will is not {V}'s. The expert compared it with known samples.\""), .direct("What did {V}'s other child say?", "\"That {V} said the farm would be split between the children. That is not what the will says.\""), .direct("How did you get involved?", "\"{V} had been a client for many years, and I drafted the original will in a different county when {V} lived there. After the death, {DL} brought in a new will.\""), .direct("What did the original will provide?", "\"The farm to be split equally between {V}'s two children, with some cash gifts to a church. It was signed in my office with two staff witnesses.\""), .direct("What did you notice about the new will?", "\"The signature looked shaky and the loops were different from {V}'s signature on file. Both witnesses were friends of {DL}, which is unusual.\""), .cross("{D} says {V} signed it, doesn't {D.he}?", "\"Yes. {DL} says {V} signed it freely. The two witnesses agree they saw it.\""), .cross("Was there an older will?", "\"Yes, drafted in a different county. It is old and says something different.\""), .cross("Could {V}'s signature have changed with illness?", "\"It can change. The expert said it still does not match.\""), .cross("A person's signature does change with age and illness, doesn't it?", "\"It does. That is why we hired a document examiner.\""), .cross("You cannot say who held the pen, can you?", "\"No. I know only what the examiner concluded and what I observed.\"")],
        defenseRole: "Witness to will",
        defenseExam: [.direct("Did you see {V} sign the will?", "\"Yes. I was in the room, and I watched {V} sign. {V} knew what the document was.\""), .direct("Was {V} clear-headed at the time?", "\"{V} was medicated, but alert enough to talk and understand. I would not say {V} was confused.\""), .direct("Did {D} pay you to be a witness?", "\"Not exactly. I was bought lunch. I did not think of it as payment.\""), .direct("How do you know the defendant?", "\"We have been friends for fifteen years, and I help with harvest each fall. I was at the house the day of the signing.\""), .direct("What did you see?", "\"{V} sat at the kitchen table, picked up a pen, and signed the will slowly. {D} held the paper steady.\""), .direct("How did {V} seem?", "\"Tired but clear. {V} asked for water and said something about the farm and the work.\""), .cross("Are you a friend of the defendant?", "\"Yes. I know {D.he} well. I understand why that matters.\""), .cross("How long did the signing take?", "\"A few minutes. {V} was tired, and the pen shook.\""), .cross("Did anyone from {V}'s family attend?", "\"No. It was just us and {DF}.\""), .cross("You are close to the defendant, aren't you?", "\"Yes, and I know that makes some people doubt me.\""), .cross("You were bought lunch that day, weren't you?", "\"Yes, a sandwich afterward. I did not take any money.\"")],
        theory: ("{D} forged a will.", "A real will."),
        allocution: "\"I'm sorry for the family's grief. I did not forge anything. My father signed that will in front of two witnesses, and I trusted them. I loved that farm and I loved {V.him}. I'm asking the court to look carefully at who saw it signed.\"",
        truths: ("{DL} paid the witnesses.", "The older will was drafted in a different county."),
        defendant: [.direct("Did you forge {V}'s will?", "\"No. I did not forge anything. {V} signed that will in front of two witnesses.\""), .direct("Why were your friends the witnesses?", "\"They were who I had. I trusted them. They saw {V} sign.\""), .direct("Did you pay the witnesses?", "\"I bought them lunch. It was not a payment. I thanked them for helping.\""), .direct("What was {V}'s health like at the end?", "\"Failing quickly, with heart trouble and a lot of pain medicine. {V} was mostly in bed in the last two weeks.\""), .direct("How did the signing happen?", "\"I invited two friends to the house, and {V} signed at the kitchen table with my help steadying the paper. {V} said the farm should go to the one who worked it.\""), .direct("Why did you work the farm?", "\"I stayed on it for twenty years after my sibling moved away. {V} had promised me it would be mine.\""), .cross("The handwriting expert says the signature is not {V}'s, doesn't {V.he}?", "\"The expert is wrong, I believe. {V} was ill, and the signature looked different.\""), .cross("An older will exists. Why is it different?", "\"It is old. {V} changed {V.his} mind. I am not hiding it.\""), .cross("You are the one who benefits from this will, aren't you?", "\"Yes. But that does not make it fake.\""), .cross("You benefit from this will, don't you?", "\"Yes, I get the farm. But that does not mean I forged it.\""), .cross("The witnesses you chose were your friends, weren't they?", "\"Yes. I did not think to call in strangers.\"")],
        openings: ("After {V} died, {D} presented a will leaving the farm to {DL}. A handwriting expert says the signature is not {V}'s, and the two witnesses were friends of {DL}.", "The defense witnesses will explain that {V} signed in front of witnesses while ill and medicated, which can change a signature, and that {V} changed {V.his} mind."),
        closings: ("A signature that is not {V}'s, two witnesses who are {D}'s friends, and a farm that was supposed to be split. Only {DL} gains from this will.", "A will signed by an ill person in front of two witnesses. The State must prove forgery, and an expert's opinion on a shaky signature is not certainty."),
        timeline: [(-14, "{V}'s health fails."), (0, "{V} dies."), (7, "The will is presented."), (30, "The report.")],
        identified: "A handwriting report.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "{D.He} cut out {D.his} brothers. For forty years we worked on that farm with our father, and when {V.he} died we found a will that left it to one son. Our father never would have done that. We've stopped talking at Christmas. It has torn our family apart.",
        doctrines: ["expertTestimony"],
        genders: ["D": .male])

    static let barSkimmerPocket = SmallCases.make(
        key: "story.barSkimmerPocket",
        category: .whiteCollar,
        headlines: ["Bartender Copies Customers' Cards With Pocket Skimmer", "Same Bar, Same Fraud Alerts"],
        law: "cardFraud",
        threshold: 7,
        spec: "Used a device to copy payment card data of {V} and others, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Eleven customers of one bar reported fraud on {DATE}. A pocket skimmer was found in the apron of {D}, a bartender. {DL} says it was a lost item.",
        state: [E(.physical, 3, "Skimmer", "In {D}'s apron.", .search), E(.digital, 3, "Card Data", "Eleven cards on the device."), E(.document, 2, "Fraud Alerts", "All used at the bar.")],
        defense: [E(.statement, 1, "Lost Item", "{DL} says it was lost property.")],
        role: "Bar owner",
        exam: [.direct("What did customers report on {DATE}?", "\"Eleven customers of my bar reported fraud on their cards. All of the fraudulent charges followed their visits to the bar.\""), .direct("What was found on {DL}?", "\"A pocket skimmer in the apron of {D}, my bartender. The device held data from eleven cards.\""), .direct("What do the fraud alerts show?", "\"All eleven cards were used fraudulently after being used at my bar. The pattern points to something at the bar.\""), .direct("How did the cards get compromised?", "\"I believe a device was attached at my register. Every card used there that week was later used fraudulently.\""), .direct("How did you find the skimmer?", "\"I asked a deputy to check the staff aprons at closing. The device was in the front pocket of the apron {DL} had worn that night.\""), .direct("What did the device hold?", "\"Data from eleven cards, with names and numbers. Those matched the customers who had called.\""), .cross("{DL} says it was lost property, doesn't {D.he}?", "\"Staff do find things. But a skimmer in an apron is not an ordinary lost item.\""), .cross("Do staff share aprons?", "\"Sometimes, yes. It's not uncommon for aprons to get mixed up on busy nights.\""), .cross("Did you see {DL} swipe a card?", "\"No. I didn't see anything like that. I only know what was found.\""), .cross("Four staff members wear those aprons, don't they?", "\"Yes, and they hang on the same hook by the back door. I cannot say who wore which one on a given night.\""), .cross("{D} was a good employee until then, wasn't {D.he}?", "\"Yes, for three years. I never had a complaint about {D.his} handling of cash.\"")],
        defenseRole: "Bartender coworker",
        defenseExam: [.direct("How long have you worked at the bar?", "\"Almost four years behind the bar. I work most Friday and Saturday nights.\""), .direct("How do the aprons work?", "\"We keep a rack of six or seven by the back door, and whoever is on takes one. Most people have a favorite, but we mix them up.\""), .direct("Have you worn {D}'s apron?", "\"Yes, many times, especially when it was the only one left on the hook. We joke about whose is whose.\""), .direct("What kind of employee is the defendant?", "\"Reliable and honest, someone who has returned a lost phone and a wallet. I have never seen {D} do anything improper with a card.\""), .direct("Did you see anything that night?", "\"A busy night with a full house, nothing unusual. I did not see anyone pull out a device.\""), .direct("What did you think when you heard about the skimmer?", "\"I was shocked. I thought of every card I had run that week.\""), .cross("You did not see who put it in the apron, did you?", "\"No. I never saw it before the deputies found it.\""), .cross("Not every employee shares aprons, do they?", "\"No. A few of us keep our own and watch them.\""), .cross("You cannot say who had access to the apron that afternoon, can you?", "\"Not precisely. Several of us went through the back.\""), .cross("You did not see the defendant use any card, did you?", "\"No. I was working my own side.\""), .cross("A skimmer in an apron is a serious thing, isn't it?", "\"Very serious. That is why I want to know how it got there.\"")],
        theory: ("{D} skimmed cards.", "Lost property."),
        allocution: "\"I'm sorry for the customers who lost money. I found that device and thought it was lost property, so I put it in my apron to give to the owner, and then I forgot. I never used it, and I wouldn't know how. I'd never steal from the people I serve.\"",
        truths: ("{DL} used one card for a purchase.", "Four staff share aprons."),
        defendant: [.direct("Why was a skimmer in your apron?", "\"I found it. I thought it was lost property. I put it in my apron to give to the owner, and then I forgot.\""), .direct("Did you use it on customers' cards?", "\"No. I never used it. I wouldn't know how. I'm not that kind of person.\""), .direct("Do other staff use your apron?", "\"Sometimes. Aprons get shared. Someone else could have left it in mine.\""), .direct("How did you come to have the device?", "\"I found it on the floor near the back bar while cleaning. It looked like a small card reader, and I put it in my apron to give to the owner.\""), .direct("Why did you not hand it over?", "\"I forgot with the busy night and the rush of customers. I meant to mention it at closing.\""), .direct("What do you do with customers' cards?", "\"I take them, run them on the bar terminal, and hand them back. I never carry a card out of sight.\""), .cross("The skimmer had eleven cards on it, didn't it?", "\"That's what they say. I never knew. I didn't look at it.\""), .cross("You didn't turn it in, did you?", "\"No. I meant to. I forgot. I should have given it to the owner.\""), .cross("It was in your apron, wasn't it?", "\"Yes. I know how that looks. I didn't put the cards on it.\""), .cross("You used one card for a purchase on that device, didn't you?", "\"I swiped my own card through it once to see what it was. I did not realize it was recording data.\""), .cross("You are the only one who touched that apron that night, aren't you?", "\"I wore it all evening. I cannot say who touched it before my shift.\"")],
        openings: ("Eleven customers of one bar reported card fraud, and a pocket skimmer holding data from eleven cards was found in {D}'s apron. The State will show the skimmer, the card data, and the fraud alerts.", "Jurors will also see a bar where aprons are shared, a device found and kept to hand to the owner, and no one who saw {D} swipe a card."),
        closings: ("Eleven cards, all used at one bar, and a skimmer with eleven cards in the bartender's apron. The device was on {D}.", "Aprons are shared at that bar, and no one saw {D} use the skimmer. The State has not proved {DL} knew what was in that apron."),
        timeline: [(-14, "Alerts begin."), (0, "Closing: the search."), (0, "Midnight: the skimmer."), (1, "{DL} is arrested.")],
        identified: "A skimmer.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "My account was drained overnight. I stopped for a drink after work like I do on Fridays, and the next morning my rent money was gone. It took weeks to get through to the bank, and I had to borrow to cover my bills. I trusted that place.",
        doctrines: ["searchSeizure"])

    static let loyaltyCardClones = SmallCases.make(
        key: "story.loyaltyCardClones",
        category: .whiteCollar,
        headlines: ["Cashier Cloned Loyalty and Gift Cards at the Register", "Balances Vanish Across Town"],
        law: "cardFraud",
        threshold: 7,
        spec: "Used a device to copy and reuse card data of {V} and others, totaling $9,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Gift card balances vanished after being swiped at a store register run by {D}. A reader hidden under the till copied data on {DATE}. {DL} says the reader was for coupons.",
        state: [E(.physical, 3, "Hidden Reader", "Under the register.", .search), E(.digital, 3, "Clone Logs", "Data from sixty cards."), E(.video, 2, "Register Camera", "{D} swipes twice.")],
        defense: [E(.statement, 1, "Coupons", "{DL} says the reader was for coupons.")],
        role: "Store manager",
        exam: [.direct("What did you discover at the register?", "\"A hidden reader under the till at a register run by {D}. It copied data from gift cards when they were swiped.\""), .direct("How many cards were cloned?", "\"Data from sixty cards. The clone logs show it. Balances vanished after the cards were swiped.\""), .direct("How did you find the reader?", "\"A customer complained that a gift card balance had drained after a sale at register three. I checked the register and found a small reader taped under the till.\""), .direct("What was on it?", "\"A log of sixty card swipes with account numbers and balances, going back about four weeks. They matched the drained cards.\""), .direct("What does the register camera show?", "\"It shows {DL} swiping a card at the register, then swiping it a second time through a slot under the counter. It repeated for many customers.\""), .direct("What did you do after you found the reader under the till?", "\"I photographed it where it sat and did not touch it. I called the store owner and the sheriff's office and kept the register closed.\""), .cross("{D} says the reader was for coupons, doesn't {D.he}?", "\"Yes. We do have a coupon program, and I know that.\""), .cross("Did the defendant buy the reader online?", "\"I understand so. I did not know that when I found it.\""), .cross("Is swiping twice ever normal?", "\"Sometimes a card fails the first time. But twice every time is not normal.\""), .cross("Does the coupon reader plug into the register?", "\"No. It's a separate small device, and it isn't connected to our system.\""), .cross("No one else worked that register, did they?", "\"Two part-timers covered some shifts. {D.He} was on most of the dates the logs cover.\"")],
        defenseRole: "Marketing manager",
        defenseExam: [.direct("Is there a coupon program at the store?", "\"Yes, there is a coupon program, and we have run it for a couple of years now with good results.\""), .direct("Does the coupon program need a special card reader?", "\"No. It does not. Coupons are scanned with the normal register equipment, and no extra reader is needed at all.\""), .direct("Did you ever ask {D} to use a separate reader for coupons?", "\"No. I did not. I do not know why {D} would think a separate device was needed for that.\""), .direct("What is your role?", "\"I manage marketing for the store, including the loyalty coupon program. I design the offers and send them to customers.\""), .direct("How does the program work?", "\"Customers scan their loyalty card or phone at checkout and the register adds the coupon automatically. We do not need any extra devices.\""), .direct("Did you ask the defendant to try anything new?", "\"No. I never asked for a separate reader.\""), .cross("Did you know about the reader hidden under the till?", "\"No. I did not know about it until it was found, and I was surprised to learn it was there.\""), .cross("Who had access to the register area besides the defendant?", "\"{DF} and a few other staff members did. I cannot say who else may have reached under the till.\""), .cross("Did the defendant ever mention the reader to you in any way?", "\"No, I do not recall that. It never came up in any of our meetings about the coupons.\""), .cross("Other staff use that register too, don't they?", "\"A few do, and the till area is open to them.\""), .cross("The coupon program never needed a separate reader, did it?", "\"Not that I know of. Coupons are scanned on the main reader, and I did not ask {D.him} to install any other device.\"")],
        theory: ("{D} cloned cards.", "Coupons."),
        allocution: "\"I'm sorry for the customers who lost their balances. I did not clone anything. The reader I used was for coupons, and I ordered it online for a coupon project I thought would help the store. I'd never take a customer's money, and I'd gladly show the court how it worked.\"",
        truths: ("{DL} bought the reader online.", "The coupon program was real."),
        defendant: [.direct("Did you clone gift cards?", "\"No. I did not clone anything. The reader I used was for coupons.\""), .direct("Where did you get the reader?", "\"Online. I ordered it for a coupon project I thought would help the store.\""), .direct("Why did you swipe cards twice?", "\"Habit. I swipe twice to be sure it registers.\""), .direct("Where did you buy the reader?", "\"Online for about $40. The listing said it could store customer loyalty data for coupon use.\""), .direct("What did you plan to do with it?", "\"Offer birthday coupons to repeat customers. I thought I could read the loyalty cards and send them offers.\""), .direct("Who knew about it?", "\"I told one coworker I was trying something for the coupon program. I did not tell the manager.\""), .cross("The reader was hidden under the till, wasn't it?", "\"It was out of the way. I did not mean to hide it. I put it where it fit.\""), .cross("Sixty cards were cloned. How do you explain that?", "\"I cannot explain it. I did not copy data from cards on purpose.\""), .cross("The coupon program does not need a reader, does it?", "\"Maybe not. I thought it would help.\""), .cross("You never asked the manager about the reader, did you?", "\"No. I wanted to surprise everyone with the result.\""), .cross("Sixty cards were read by a device under your till, weren't they?", "\"Yes, that is what the log shows. I did not know it stored their balances.\"")],
        openings: ("Gift card balances vanished after being swiped at a register run by {D}. A hidden reader under the till copied data from sixty cards, and the register camera shows {DL} swiping each card twice.", "The defense case is that the store ran a real coupon program and that {D} bought a reader online for it, with no plan to clone any card."),
        closings: ("A hidden reader, sixty cloned cards, and a clerk swiping twice on camera. This is not how a coupon program works, and the balances disappeared at {D}'s register.", "A real coupon program, a reader bought online, and a habit of swiping twice. The State must prove {D} used the reader to steal, and it cannot."),
        timeline: [(-30, "The reader is placed."), (0, "Month 1: balances vanish."), (0, "Month 1: the search."), (1, "{DL} is arrested.")],
        identified: "A hidden reader.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        doctrines: ["burdenOfProof"])

    static let electronicsCloneRing = SmallCases.make(
        key: "story.electronicsCloneRing",
        category: .whiteCollar,
        headlines: ["Group Bought Electronics With Cloned Gift Cards", "Receipts Stacked in a Rental Car"],
        law: "cardFraud",
        threshold: 7,
        spec: "Used cloned payment card data to obtain goods valued at $22,000 from {V}, a retailer, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A group bought electronics with cloned gift cards at five stores on {DATE}. Receipts and fifty blank cards were in the rental car of {D}. {DL} says {D.he} was only the driver.",
        state: [E(.physical, 3, "Rental Car", "Fifty blank cards and receipts.", .search), E(.video, 3, "Store Cameras", "{D} enters stores."), E(.digital, 2, "Card Encoder", "An encoder in the trunk.")],
        defense: [E(.statement, 1, "Driver", "{DL} says {D.he} only drove.")],
        role: "Loss prevention officer",
        exam: [.direct("What did you see on {DATE}?", "\"A group bought electronics with cloned gift cards at five stores. Our cameras show {D} entering the stores.\""), .direct("What was found in the rental car?", "\"Fifty blank cards and receipts. There was also a card encoder in the trunk.\""), .direct("What does that combination suggest?", "\"Blank cards plus an encoder is how you clone gift cards. The receipts match purchases at the five stores.\""), .direct("How did the group operate?", "\"Four people split up and entered five electronics stores in one day. They used gift cards with real magnetic data but made to look like store brand cards.\""), .direct("How did you follow them?", "\"We gathered the camera footage and the stores' receipts. {D.He} appears in the entrance of three of the five stores and carries two bags out of one.\""), .direct("What happened at the stop?", "\"Deputies stopped the rental car at two, found receipts for about $9,000 in electronics, fifty blank cards, and a card encoder under a blanket in the trunk.\""), .cross("{DL} says {D.he} was only the driver, doesn't {D.he}?", "\"The cameras show {DL} entering the stores, not just waiting in the car.\""), .cross("Did you see {DL} use a card?", "\"I'd have to review the footage. {D.He} enters stores, but I can't say each time a card was swiped.\""), .cross("Who else was in the group?", "\"Others. I don't know them all. The video shows several people, and I can't identify each.\""), .cross("{D} was not the one who paid at each store, was {D.he}?", "\"I have seen {DL} handling bags more than cards. I would need to check each clip for a card.\""), .cross("The car was rented in the defendant's name, but others were in it, weren't they?", "\"Yes, four people. The rental papers list only {DL}.\"")],
        defenseRole: "Rental agent",
        defenseExam: [.direct("Do you remember renting the car to {DL}?", "\"Yes. {D} rented a mid-size car for a few days, with ID and a card.\""), .direct("Who rented it?", "\"The paperwork lists {DF} as the person who rented it, and that is the name on the receipt.\""), .direct("Were other drivers listed?", "\"No. Only {DF}. But anyone could drive it if {DF} allowed.\""), .direct("How does your rental office handle returns?", "\"We check mileage, fuel, and damage, and we clean the interior. We do not open trunks unless there is a reason.\""), .direct("Did you see the customer's license?", "\"Yes. I copied the number into the rental agreement, and the agreement carries the signature.\""), .direct("How many drivers were on the contract?", "\"Only {DF}. Others could drive if the renter allowed it.\""), .cross("Who used the car?", "\"Several people, as far as I know. I only handled the rental.\""), .cross("Do you know what was in the trunk?", "\"No. We don't inspect trunks at return. I couldn't tell you.\""), .cross("Did {DL} return it on time?", "\"I believe so. I don't recall any issues with the return.\""), .cross("You took a deposit on a card in {DF}'s name, didn't you?", "\"Yes, we took a deposit on the card the renter showed, and the name on the card matched the driver's license.\""), .cross("You never saw what was in the trunk, did you?", "\"No. We do not check trunks, and I had no reason to.\"")],
        theory: ("{D} used cloned cards.", "Only a driver."),
        allocution: "\"I was the driver, and I drove those people from store to store, and I didn't know they were using cloned cards. I went in with them and bought a few things for myself. I'm sorry for what the stores lost, and I wish I'd asked more questions.\"",
        truths: ("{DL} carried two shopping bags.", "{DL} was paid $300 for driving."),
        defendant: [.direct("What was your role that day?", "\"I was the driver. I drove the group around. I didn't know they were using cloned cards.\""), .direct("Why did you enter the stores?", "\"To buy a few things for myself. I went in with the others. I didn't know what they were doing.\""), .direct("Did you know about the blank cards?", "\"No. They were in the car, but I never saw them. I rented the car and left others to use it.\""), .direct("How did you come to drive that day?", "\"A friend asked me to drive the group around for a few hours in exchange for $300. I took the job because I needed cash.\""), .direct("What did you do inside the stores?", "\"I walked in to look at a phone case and a pair of headphones for myself. I carried two bags back to the car for others.\""), .direct("What did you think was going on?", "\"That they were shopping and had good deals. I did not look at what they paid with.\""), .cross("You rented the car, didn't you?", "\"Yes. I did. Others used it. I didn't think about what was inside.\""), .cross("The encoder was in the trunk, wasn't it?", "\"That's what deputies say. I never opened the trunk. I didn't know.\""), .cross("You went into all five stores, didn't you?", "\"Some of them. I was with friends. I thought we were shopping.\""), .cross("You were paid $300 for driving, weren't you?", "\"Yes, and that was a lot for a few hours. I did not ask why.\""), .cross("You carried two shopping bags back to the car, didn't you?", "\"Yes, I carried two bags to the car for the others. I did not look inside, and I thought they were just purchases.\"")],
        openings: ("A group used cloned gift cards to buy electronics at five stores. Fifty blank cards, receipts, and an encoder were in the rental car of {D}, and cameras show {DL} entering the stores. The State will present the loss prevention officer.", "The defense will point you to a driver who rented a car that others used, who never saw the blank cards, and who thought the group was shopping."),
        closings: ("Fifty blank cards, an encoder, receipts, and {D} on camera in the stores. A driver who walks into three stores and carries bags out is part of the operation, not just a chauffeur.", "{D} rented the car and drove friends around for $300. The State has not proved {DL} knew about the cards or the encoder, and nothing shows {DL} swiping a single cloned card."),
        timeline: [(0, "10 a.m.: store one."), (0, "1 p.m.: store five."), (0, "2 p.m.: the stop."), (0, "2:30 p.m.: the search.")],
        identified: "Cameras and a search.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .divided,
        doctrines: ["searchSeizure"])

    static let deadWomanAccounts = SmallCases.make(
        key: "story.deadWomanAccounts",
        category: .whiteCollar,
        headlines: ["Man Took Over Dead Woman's Accounts and Spent $53,000", "Obituary Date Beats the Logins"],
        law: "identityTheft",
        threshold: 8,
        spec: "Knowingly obtained and used identifying information of {V}, a deceased person, to obtain credit, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "After {V} died, {D} logged into her accounts and spent $53,000 on {DATE}. Logs showed {DL}'s phone. {DL} says {V} had given {D.him} access.",
        state: [E(.digital, 3, "Account Logs", "Logins from {D}'s phone."), E(.document, 3, "Death Certificate", "{V} died three weeks before."), E(.document, 2, "Purchases", "$53,000.")],
        defense: [E(.statement, 1, "Access", "{DL} says {V} had shared access.")],
        role: "Bank investigator",
        exam: [.direct("What did you find in {V}'s accounts?", "\"After {V} died, someone logged in and spent $53,000 on {DATE}. The logins came from {D}'s phone.\""), .direct("When did {V} die?", "\"Three weeks before. The death certificate is in evidence. {V} could not have made those purchases.\""), .direct("What do the purchases show?", "\"$53,000 in spending. The account logs show the logins and the purchases lined up.\""), .direct("How did the bank learn of the death?", "\"The family notified us three weeks after {V} died. By then the accounts had been accessed from a device that we later traced to {DL}'s phone.\""), .direct("What did the log show about the activity?", "\"Logins to the checking, savings, and a credit card in the days after the funeral. Transfers and purchases totaled $53,000, including a large payment to a dealership.\""), .direct("What was bought?", "\"A used pickup truck, furniture, and several payments on a personal loan. We have receipts for each.\""), .cross("{DL} says {V} had given {D.him} access, doesn't {D.he}?", "\"Some access was granted on one account. But access ends in practice when an account holder dies.\""), .cross("Was {DL} an authorized user on any account?", "\"One, I'm told. A savings account. That's not the same as every account.\""), .cross("Did {DL} use only that account?", "\"No. The logs show logins to several of {V}'s accounts.\""), .cross("{V} did add {D} to one account earlier, didn't {V.he}?", "\"Yes, to a savings account. The authorization ended at death.\""), .cross("The logins came from the defendant's phone and nobody else's, didn't they?", "\"Correct. The device ID matches the phone seized from {D.him}.\"")],
        defenseRole: "Bank clerk",
        defenseExam: [.direct("What is your role at the bank?", "\"I am a branch clerk handling deposits, account changes, and customer questions at the window. I have worked at this bank for six years.\""), .direct("What do your records show about {D}'s access to {V}'s accounts?", "\"{D} was added as an authorized user on a savings account about two years ago, with a form signed by {V}. No other accounts list {DF}.\""), .direct("What does being an authorized user on that account allow?", "\"Viewing the balance, making deposits, and making withdrawals on that one savings account. It does not extend to checking, credit cards, or any other product.\""), .direct("Did the bank ever add the defendant to the checking account?", "\"No. Our records show only the savings account. A change to checking would have required a new form and a signature from {V}.\""), .direct("Does an authorized user keep access after the account holder dies?", "\"No. The bank freezes the accounts once we are notified of the death, and authorizations end at that point. We ask families to tell us quickly.\""), .direct("What did you see when the activity was reviewed?", "\"Logins to several accounts after the date of death, including ones {DF} was never added to. That is when the bank investigator was brought in.\""), .cross("The checking account and the credit card were never in the defendant's name, were they?", "\"That is correct. {D.He} had no authority on either of those under our records.\""), .cross("Did the defendant ever notify the bank that {V} had passed away?", "\"I do not recall any such call, and our system shows the notice came from the family three weeks later.\""), .cross("You cannot say what {V} told the defendant in private, can you?", "\"No. I only know what is on the forms in our file.\""), .cross("A verbal permission would not change the bank's records, would it?", "\"No. Verbal permission does not create account access at our bank, and it would not survive a death.\""), .cross("The login activity was from the defendant's phone, wasn't it?", "\"That is what the investigator told me. I did not review the device logs myself.\"")],
        theory: ("{D} used a dead woman's accounts.", "Shared access."),
        allocution: "\"{V} gave me access to the accounts before {V.he} died, and I was grieving, and I thought I was carrying out {V.his} wishes. I wasn't thinking about the law. I understand now how it looks to {V.his} family. I'll do whatever I can to account for every dollar.\"",
        truths: ("{DL} bought a truck.", "{V} had added {DL} to one account earlier."),
        defendant: [.direct("Why did you log into {V}'s accounts?", "\"{V} had given me access before. I thought I could use it to pay for some things {V} had wanted done.\""), .direct("Did you know {V} had died?", "\"Yes. I knew. I was grieving, and I thought I was carrying out {V}'s wishes. I wasn't thinking about the law.\""), .direct("What did you spend the money on?", "\"Some bills and some things I needed. I know I shouldn't have. I told myself it was what {V} would want.\""), .direct("What was your relationship with {V}?", "\"I was a caregiver for the last two years and lived nearby. I handled shopping, errands, and some bills.\""), .direct("What did {V} say about the accounts?", "\"{V} said more than once that I could use the accounts for whatever I needed and that I had earned it. I took that as permission.\""), .direct("What did you buy?", "\"A truck for getting around and furniture for my apartment, plus some bills I had behind. I did not tell the family.\""), .cross("You spent $53,000 after {V} died, didn't you?", "\"Yes. I did. It was too much. I should have stopped.\""), .cross("You only had access to one account, didn't you?", "\"Officially. But {V} had told me I could use what I needed. I took that too far.\""), .cross("Nobody gave you permission after {V} died, did they?", "\"No. I knew that. I used it anyway.\""), .cross("Did {V}'s family give the okay?", "\"No. No one in the family knew about it, and no one gave permission.\""), .cross("Nothing in writing gave you access to the checking account, did it?", "\"No. Only the savings account. The rest was verbal.\"")],
        openings: ("Three weeks after {V} died, someone logged into {V}'s accounts from {D}'s phone and spent $53,000. The State will show the death certificate, the account logs, and the purchases.", "The defense will present a caregiver who had access to one account, believed {V} wanted {D.him} to use the money, and acted openly under a real name."),
        closings: ("{V} was dead, and the logins came from {D}'s phone while $53,000 was spent. Access to one savings account never reached the checking account, the credit card, or a truck from a dealership.", "{D} had been given access and believed it was what {V} wanted. The State has not proved {DL} meant to steal, and the savings account permission shows a close and trusted bond."),
        timeline: [(-21, "{V} dies."), (0, "The logins."), (21, "The statement arrives."), (22, "The family reports.")],
        identified: "Account logs.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "{V.He} was my mother, and we were still sorting through {V.his} things when we saw the charges. Someone had spent fifty-three thousand dollars from {V.his} accounts in the days after we buried {V.him}. We didn't even have the sympathy cards put away yet. I'll never understand how someone could do that.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male, "V": .female])

    static let loanForgivenessPhone = SmallCases.make(
        key: "story.loanForgivenessPhone",
        category: .whiteCollar,
        headlines: ["Caller Collected Fees for a Fake Student Loan Forgiveness Program", "Fifty Victims, $60 Each"],
        law: "identityTheft",
        threshold: 7,
        spec: "Obtained identifying information of {V} and others and used it to obtain payments, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} called fifty people on {DATE} promising student loan forgiveness for a $60 fee and collected their account numbers. {DL} says the program was real. The calls came in the first week, the $60 fees followed in the second, and complaints began in the third.",
        state: [E(.digital, 3, "Call Records", "Fifty calls from {D}'s phone."), E(.document, 3, "Payment Records", "$3,000 collected."), E(.statement, 2, "Victim", "'He had my loan number.'")],
        defense: [E(.statement, 1, "Real", "{DL} says the program was real.")],
        role: "Victim",
        exam: [.direct("What did the caller offer you?", "\"Student loan forgiveness for a $60 fee. The caller already had my loan number and asked for my account numbers.\""), .direct("How many calls did {D} make?", "\"Fifty, according to the call records. The calls came in the first week, and the $60 fees followed in the second.\""), .direct("How much was collected?", "\"$3,000 in all, according to the payment records. Complaints began in the third week.\""), .direct("How did the call begin?", "\"A caller said they represented a federal student loan relief program and that I qualified for forgiveness. The caller already knew my loan number.\""), .direct("What did you pay?", "\"$60 as an application fee, which I paid by card over the phone. I was promised a letter within ten days.\""), .direct("What happened after?", "\"Nothing came. I called back, and the number had a voicemail that said the box was full.\""), .cross("{D} says the forgiveness program was real, doesn't {D.he}?", "\"Yes. A web page does list a program. I do not know whether it is what {D} sold.\""), .cross("Did you pay the $60 yourself?", "\"Yes. I paid, because I believed I would get help with my loan.\""), .cross("Did any victim get forgiveness?", "\"I do not know of anyone who did. My loan did not change.\""), .cross("You have federal student loans, don't you?", "\"Yes, and that is why the offer sounded believable. It even mentioned the servicer.\""), .cross("You did not check the program's name with the government before paying, did you?", "\"No. I trusted the caller because the caller knew my number.\"")],
        defenseRole: "Web designer",
        defenseExam: [.direct("Did you build a web page for {D}?", "\"Yes. I built a page that described a student loan forgiveness program, as {D} asked me to.\""), .direct("Was the program real?", "\"I am not sure. {D.He} told me it was. I built the page from what {D.he} gave me.\""), .direct("Did the defendant seem honest about it?", "\"{DF} seemed sure. I did not have a reason to doubt {DF}, but I did not check either.\""), .direct("What is your work?", "\"I build websites for small businesses. I made a landing page for a loan forgiveness program for {D.him}.\""), .direct("What did the defendant tell you?", "\"That it was a service that helped people apply for forgiveness. I wrote the text from a few bullet points.\""), .direct("What did the page include?", "\"A description, a $60 fee, and a contact form. I did not add a form for account numbers.\""), .cross("Did you check whether the program existed?", "\"No. I only built the page. I did not research the program itself.\""), .cross("Did the defendant pay you?", "\"Yes. {D.He} paid me for the page. I did not ask where the money came from.\""), .cross("Did the page ask for account numbers?", "\"I do not recall. It asked for contact information and a fee.\""), .cross("You never checked whether the program was real, did you?", "\"No. I only built what I was asked to build.\""), .cross("{D} paid you before any complaints, didn't {D.he}?", "\"Yes, $400, and that was long before I heard anything.\"")],
        theory: ("{D} ran a loan scam.", "A real program."),
        allocution: "\"I believed the program was real, and I called people to offer it and collected a processing fee. I sold their numbers as leads to a broker because I thought it was part of how it worked. I should have checked more carefully, and I regret the harm to every person on those calls.\"",
        truths: ("{DL} sold the numbers to a broker.", "A web page lists the program."),
        defendant: [.direct("Was it a scam?", "\"No. I believed the program was real. I called people to offer it and collected a fee for processing.\""), .direct("What happened to the account numbers?", "\"I sold them as leads to a broker. I thought that was part of how the program worked.\""), .direct("What happened to the loan forgiveness?", "\"It was delayed. I told people it would take time, and I honestly believed the money would be applied to their loans.\""), .direct("How did you learn about the program?", "\"A friend shared a web page listing a loan forgiveness program with a $60 application fee. I thought it was a real service.\""), .direct("How did you get phone numbers?", "\"I bought a list of people with student loans from a lead service. It had names, phone numbers, and some loan numbers.\""), .direct("What did you do with the fees?", "\"I deposited them and planned to submit applications in batches. I was waiting on the program to open.\""), .cross("You collected $3,000 and no one got forgiveness, did they?", "\"Not yet. I know it looks bad. I believed it would work.\""), .cross("You called fifty people and promised something you could not deliver, didn't you?", "\"I thought I could. I was wrong.\""), .cross("You never submitted any applications, did you?", "\"No. I kept waiting for confirmation that the program was open.\""), .cross("You sold the account numbers to a broker, didn't you?", "\"Yes, as leads. I did not think about what it did to those people.\""), .cross("You never filed a single application for anyone who paid, did you?", "\"No. I told myself I would get to them. I took the money first and the paperwork never followed, and I understand how that looks.\"")],
        openings: ("{D} called fifty people promising student loan forgiveness for a $60 fee and collected their account numbers, taking in $3,000. No one received forgiveness, and complaints started in the third week.", "The defense evidence will establish that a web page listed the program, that {D} believed it was real, and that delays are not the same as a scam."),
        closings: ("Fifty calls, $3,000 in fees, account numbers sold to a broker, and not one loan forgiven. People who owed money were told what they wanted to hear and then lost more.", "A program that appeared on a web page, a seller who believed in it, and results that were slow. The State must prove {D} knew the promise was false when the calls began."),
        timeline: [(0, "Week 1: calls."), (0, "Week 2: fees."), (0, "Week 3: complaints."), (1, "{DL} is charged.")],
        identified: "Call records.",
        aggravating: ["The offense was committed for pecuniary gain", "The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "I paid with my last sixty dollars. I'm still paying off my student loans, and the call said they could make most of it go away. I gave my account number, and nothing happened. I felt so foolish. I'd skipped a meal to scrape that fee together.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let taxAgentGiftCards = SmallCases.make(
        key: "story.taxAgentGiftCards",
        category: .whiteCollar,
        headlines: ["Caller Posing as Tax Agent Collected Gift Cards From Elderly", "Fifteen Victims in One Month"],
        law: "extortion",
        threshold: 8,
        spec: "Threatened arrest of {V} and others to obtain payment of $17,000, on or about {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} called elderly people on {DATE} posing as a tax agent and demanded gift cards or arrest. Fifteen victims paid $17,000. {DL} says {D.he} only redeemed cards for a boss.",
        state: [E(.digital, 3, "Call Records", "Calls from {D}'s phone."), E(.digital, 3, "Redemption Logs", "Cards redeemed to {D}'s account."), E(.statement, 2, "Victim", "'He said I would be arrested.'")],
        defense: [E(.statement, 1, "Boss", "{DL} says {D.he} redeemed cards for a boss.")],
        role: "Victim",
        exam: [.direct("What did the caller say to you?", "\"The caller said to be a tax agent and said I would be arrested unless I paid with gift cards. I was frightened.\""), .direct("How much did you lose?", "\"Fifteen victims paid $17,000 in total. I was one of them, and I bought gift cards and read the numbers over the phone.\""), .direct("What do the redemption logs show?", "\"The cards were redeemed to {D}'s account. The call records show calls from {D.his} phone.\""), .direct("What did you do after the call?", "\"I hung up, then called the real tax office. They told me they never ask for payment that way.\""), .direct("What did you do?", "\"I drove to a store and bought $1,200 in gift cards, then read the numbers to the caller. I was scared and did not think of calling anyone.\""), .direct("When did you realize it was a scam?", "\"The next day, when a neighbor asked about it. I called the real tax office, and they said they never ask for gift cards.\""), .cross("{D} says {D.he} only redeemed cards for a boss, doesn't {D.he}?", "\"Yes. That is what {D.he} says. I never met the boss.\""), .cross("Did you hear the caller's voice?", "\"Yes. I cannot say it was {DL}'s. The voice was a stranger's to me.\""), .cross("Did the defendant keep a share?", "\"I understand {DL} kept thirty percent. I do not know the arrangement.\""), .cross("You did not see the caller, did you?", "\"No, only a voice on the phone. I could not tell you whose it was.\""), .cross("Other people were called too, weren't they?", "\"Yes, fifteen of us. We have compared notes since.\"")],
        defenseRole: "Boss's former employee",
        defenseExam: [.direct("Did you work for the same boss that {D} says directed this?", "\"Yes. I worked for the boss for a short time. The work was calls and cards, though I did not see the details.\""), .direct("What was the boss's name?", "\"A nickname. I never knew a real name, and I do not know how to find the person now.\""), .direct("Did the defendant work for the boss too?", "\"Yes. {D} worked for the boss as well, redeeming cards and doing what was asked.\""), .direct("How did you know the boss?", "\"I answered the same online ad and worked with the boss for about two months. I only ever knew the nickname.\""), .direct("What did you do for the boss?", "\"Redeemed gift cards and sent most of the proceeds back. I did not make any calls.\""), .direct("How did the defendant come in?", "\"{DF} was in the same group chat and did the same job. We were just two people doing what the boss said.\""), .cross("Did you make calls to victims?", "\"No. I did not make those calls. I only did some paperwork and cards.\""), .cross("Did you know the calls were scams?", "\"Not at first. I figured it out later. I left when I did.\""), .cross("Did the defendant know it was a scam?", "\"I do not know. {D.He} acted like it was a normal job. But I cannot read minds.\""), .cross("You kept a share too, didn't you?", "\"Yes, thirty percent, like {DF}.\""), .cross("You learned later it was a scam, didn't you?", "\"Yes, from a news story. I stopped when I did.\"")],
        theory: ("{D} extorted the elderly.", "A boss."),
        allocution: "\"I'm so sorry for those families. I did not make those calls. I redeemed cards for a man I knew only by a nickname as part of a job, and I never knew where they came from. I wish I had asked more. I'm sorry for every person who was scared.\"",
        truths: ("{DL} kept 30% of the redemptions.", "The boss's number is in {DL}'s phone."),
        defendant: [.direct("Did you make the calls to victims?", "\"No. I did not call anyone. I redeemed cards for a boss, as part of a job.\""), .direct("Who was the boss?", "\"A contact I knew by a nickname. I do not know a real name.\""), .direct("How were you paid?", "\"I kept thirty percent of the redemptions as pay. I thought it was a commission.\""), .direct("How did you meet the person you call the boss?", "\"Online, through a group that offered quick money for redeeming gift cards. I only ever knew a nickname.\""), .direct("What were you told to do?", "\"To log into a site, redeem card numbers sent by text, and send most of the money back. I kept thirty percent as pay.\""), .direct("What did you think the cards were?", "\"I was told they were from a promotion and from customers of the boss's business. I did not ask many questions.\""), .cross("You kept thirty percent of money taken from elderly victims, didn't you?", "\"I did not know they were victims. I thought it was legitimate work.\""), .cross("Calls came from your phone, didn't they?", "\"So it seems. I did not make them. Someone else used my phone.\""), .cross("You redeemed cards to your own account. Isn't that suspicious?", "\"I should have seen it. I was told it was normal.\""), .cross("The boss's number is saved in your phone, isn't it?", "\"Yes, it is saved under the nickname. I never had another name for the boss, and I used that number to get my instructions.\""), .cross("Thirty percent of every card is a lot for a simple task, isn't it?", "\"Yes, and that should have made me ask more. I took the money.\"")],
        openings: ("{D} posed as a tax agent in calls to elderly people, demanding gift cards or arrest, and fifteen victims paid $17,000. Calls came from {D.his} phone, and cards were redeemed to {D.his} account.", "By the end of this trial, the proof will show that {D} only redeemed cards for a boss, never made the calls, and was told the work was legitimate."),
        closings: ("Calls from {D}'s phone, cards redeemed to {D.his} account, and thirty percent kept as a cut. Fifteen frightened people paid $17,000, and {DL} profited from their fear.", "A person who redeemed cards for a boss known only by a nickname and was told the work was legitimate. The State must prove {D} knew the cards came from victims."),
        timeline: [(0, "Week 1: calls."), (0, "Week 2: cards."), (0, "Week 3: reports."), (1, "{DL} is arrested.")],
        identified: "Call records.",
        aggravating: ["The victim was particularly vulnerable", "The offense was committed for pecuniary gain"],
        mood: .wantsConviction,
        impact: "I was terrified. A man called me saying I'd be arrested if I didn't buy gift cards that very day. I'm eighty-one years old and I've never been in trouble in my life. I drove to three stores and read {D.him} the numbers. I couldn't sleep for a week.",
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let wetlandsFillDump = SmallCases.make(
        key: "story.wetlandsFillDump",
        category: .property,
        headlines: ["Contractor Dumped Fill Into Protected Wetland", "Aerial Photos Show Truck Tracks"],
        law: "injuryRealProperty",
        threshold: 7,
        spec: "Willfully and wantonly injured real property of {V}, the State, causing damage of $60,000, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, a contractor, dumped forty truckloads of fill into a protected wetland on {DATE}. Aerial photos showed tracks. {DL} says the land was dry.",
        state: [E(.physical, 3, "Aerial Photos", "Tracks into the wetland."), E(.document, 3, "Delineation Map", "The area is a protected wetland."), E(.statement, 2, "Inspector", "'Forty loads.'")],
        defense: [E(.statement, 1, "Dry", "{DL} says the land was dry.")],
        role: "State inspector",
        exam: [.direct("What did your aerial photos show?", "\"Tracks leading into the wetland, where forty truckloads of fill had been dumped by {D}'s crew.\""), .direct("What does the delineation map show?", "\"The area is a protected wetland. It is marked on the map as wetland, and filling it requires a permit.\""), .direct("How many loads were dumped?", "\"Forty. I counted the tracks and the fill. It was a large amount for one site.\""), .direct("What is the wetland like?", "\"About five acres of low ground beside a creek with cattails, standing water in spring, and hydric soil. The state mapped it as a protected wetland years ago.\""), .direct("How did you learn of the dumping?", "\"A neighbor called our hotline about trucks dumping dirt behind a fence. I flew a drone over the site and saw fresh fill spread across the low ground.\""), .direct("How did you count the loads?", "\"Each truck left tire tracks and a pile that was later graded. I counted separate dump piles and truck routes, and I came to forty.\""), .cross("{D} says the land was dry, doesn't {D.he}?", "\"Yes. It can look dry in certain seasons. But the map shows what it is.\""), .cross("Were there signs marking the boundary?", "\"No. There were no signs marking the boundary. I will give you that.\""), .cross("Was the defendant told it was wetland?", "\"A surveyor told {D.him}, I understand, but not in writing.\""), .cross("No signs marked the boundary, did they?", "\"There were none posted at that time. The map was on file with the county.\""), .cross("The land can look dry in late summer, can't it?", "\"Yes, parts of it do. That is why soil and plant surveys are used, rather than a glance.\"")],
        defenseRole: "Land surveyor",
        defenseExam: [.direct("Did you warn {D} that the area was wetland?", "\"Yes, verbally. I told {D} during a site visit that the area appeared to be wetland.\""), .direct("Did you put that warning in writing?", "\"No. I did not. I only said it out loud, and I should have followed up in writing.\""), .direct("How did the defendant respond when you said it?", "\"{D.He} nodded and said {D.he} would look into it. I did not hear anything after that.\""), .direct("What did you do for the defendant?", "\"I surveyed the lot lines for a building project near the edge of the property. I walked the whole parcel.\""), .direct("What did you notice about the low ground?", "\"Dark soil and some reeds, which could signal wetland. I did not do a formal delineation.\""), .direct("How did you tell the defendant?", "\"I said out loud that the low area looked like wetland and that {D.he} should check before filling. {D.He} said fine.\""), .cross("Did you mark the boundary with stakes or signs?", "\"No. I did not mark it. There was nothing on the ground to show the line.\""), .cross("Was the area wet when you visited?", "\"It was damp in places. It can look dry in other seasons.\""), .cross("Did the defendant understand what wetland means?", "\"I think so. {D.He} is a contractor and has worked on sites like it.\""), .cross("You did not put it in your report, did you?", "\"No. My written report covered only the lot lines.\""), .cross("You did not stake the edge, did you?", "\"No, and I should have.\"")],
        theory: ("{D} filled a wetland.", "Dry land."),
        allocution: "\"I hauled forty loads onto that lot, and I thought the land was dry. A surveyor mentioned wetland to me, but I didn't believe it applied to this parcel. I should have asked for it in writing. I'll restore it however the court and the state require.\"",
        truths: ("{DL} was told by a surveyor it was wetland.", "No signs marked the boundary."),
        defendant: [.direct("Did you dump fill on the land?", "\"Yes, I did. Forty truckloads. I thought the land was dry, and I wanted to build up a pad.\""), .direct("Did you know it was a wetland?", "\"I thought it was dry. I was told about wetland by a surveyor, but I did not think it applied here.\""), .direct("Were there any signs on the land?", "\"None. There was nothing marking the boundary. I did not see any signs.\""), .direct("Why did you bring fill to that land?", "\"A client needed a building pad leveled, and a friend offered to let me dump the excess dirt behind the friend's lot. It looked like a low field.\""), .direct("What did the ground look like?", "\"Dry grass and some dried mud with a few reeds. I did not see water anywhere.\""), .direct("What did you do when the state contacted you?", "\"I stopped hauling and told the inspector what I had done. I offered to help restore it.\""), .cross("A surveyor told you it was wetland, didn't the surveyor?", "\"Yes. But verbally. I did not take it seriously. In hindsight, yes.\""), .cross("You dumped forty loads. Didn't you check the map?", "\"I did not. I should have, yes. I trusted my eyes.\""), .cross("A protected wetland is damaged now. Do you accept that?", "\"Yes. I apologize. I would like to restore it.\""), .cross("When was the wetland comment made?", "\"During a visit to the site, a few weeks before the purchase closed. I didn't write it down.\""), .cross("You never checked the county map, did you?", "\"No. A quick look would have shown it, and I did not make the time.\"")],
        openings: ("A state inspector found tracks leading into a protected wetland where {D}, a contractor, had dumped forty truckloads of fill. The delineation map shows the area as wetland, and a surveyor had warned {D.him}.", "The defense will present evidence that the land looked dry, that no signs marked the boundary, and that the warning was only spoken."),
        closings: ("Forty loads of fill in a protected wetland, a map that shows it, and a warning from a surveyor. A contractor is expected to know where a wetland is.", "Land that looked dry, no signs, and a warning never put in writing. The State must prove {D} knew it was wetland and dumped anyway."),
        timeline: [(-30, "The surveyor's warning."), (0, "Week 1: dumping."), (0, "Week 2: aerial photos."), (1, "{DL} is cited.")],
        identified: "Aerial photos.",
        mood: .divided,
        doctrines: ["mistakeOfFact"])

    static let muralPaintOver = SmallCases.make(
        key: "story.muralPaintOver",
        category: .property,
        headlines: ["Crew Painted Over Town Mural and Sprayed School Wall", "Surveillance Shows Truck"],
        law: "injuryRealProperty",
        threshold: 7,
        spec: "Willfully and wantonly injured real property of {V}, a town, causing damage of $8,400, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A town mural was painted over and a school wall sprayed on {DATE}. Surveillance showed a truck registered to {D}. {DL} says {D.he} was hired to paint.",
        state: [E(.video, 3, "Surveillance", "A truck at both sites."), E(.physical, 3, "Paint Cans", "Matching cans in {D}'s truck.", .search), E(.document, 2, "Damage Estimate", "$8,400.")],
        defense: [E(.statement, 1, "Hired", "{DL} says a customer hired {D.him}.")],
        role: "Town manager",
        exam: [.direct("What happened to the town mural?", "\"It was painted over, and a school wall was sprayed. Surveillance shows a truck at both sites.\""), .direct("Whose truck is it?", "\"It is registered to {D}. Matching cans of paint were found in the truck.\""), .direct("What did the damage cost?", "\"$8,400, according to the estimate. It covers restoring the mural and cleaning the school wall.\""), .direct("What was the mural?", "\"A forty-foot painting of the town's history on the side of the old hardware store, done by local artists and students five years ago.\""), .direct("What did you find that morning?", "\"The mural was covered in a thick layer of gray paint, and on the school wall around the corner someone had sprayed black letters. A neighbor called it in at six.\""), .direct("What did the camera show?", "\"A pickup truck passes the mural at about two in the morning and returns twenty minutes later. The same truck later parks near the school.\""), .cross("{D} says {D.he} was hired to paint, doesn't {D.he}?", "\"Yes. {DL} said a customer hired {D.him} to paint. I cannot say the customer is not real.\""), .cross("Did the defendant owe the town a fine?", "\"Yes. {D.He} owed the town a fine. I know that is a motive question.\""), .cross("Did you see the defendant at either site?", "\"No. Surveillance shows the truck, not {DL}.\""), .cross("You cannot see the driver on the footage, can you?", "\"No. The cameras are far and the truck is dark. We traced the plate.\""), .cross("The paint could be bought at any hardware store, couldn't it?", "\"Yes, a lot of people use gray paint. The cans in the truck matched the brand and color.\"")],
        defenseRole: "Customer",
        defenseExam: [.direct("Did you hire {D} to paint?", "\"Yes, for another wall. I hired {D} to paint a wall at my place.\""), .direct("Was it the town's mural?", "\"No. It was a different wall, not the mural and not the school.\""), .direct("When did you hire the defendant?", "\"A few days before that date. We agreed on the job and a price.\""), .direct("How do you know the defendant?", "\"I hired {D.him} to paint a fence on my property. We agreed on a price over the phone.\""), .direct("When was the job?", "\"That same week, in the evening after dinner. {D.He} came with a truck and paint.\""), .direct("What did you see?", "\"{D.He} painted a stretch of my fence by the road. It was the only job I hired {D.him} for.\""), .cross("Where was your wall?", "\"On my own property. It had nothing to do with the town's mural.\""), .cross("How did the defendant get the paint?", "\"I do not know. {D.He} brought the paint to my job.\""), .cross("You did not hire the defendant to paint a mural, did you?", "\"No. I never asked {D.him} to do anything outside my yard.\""), .cross("You do not know where the defendant went afterward, do you?", "\"No. After the work I went inside.\""), .cross("You never saw what was painted over, did you?", "\"No. I met {D.him} at my own house and discussed a small job. I did not hear anything about a mural or a school until later.\"")],
        theory: ("{D} defaced a mural.", "A paint job."),
        allocution: "\"I'm sorry for what happened to that mural. I was hired to paint a different wall, and I did not paint the town mural or spray the school wall. My truck was in that area for a job. I respect public art, and I'd be glad to help restore it.\"",
        truths: ("{DL} owed the town a fine.", "A work order exists in {DL}'s phone."),
        defendant: [.direct("Did you paint over the mural?", "\"No. I was hired to paint a different wall. I did not paint the town mural.\""), .direct("What about the school wall?", "\"I did not spray it. I never touched it.\""), .direct("Do you owe the town a fine?", "\"Yes. I owed the town a fine. It had nothing to do with this.\""), .direct("What is your work?", "\"I paint houses and fences for a living, and my truck carries cans and brushes at all times. People hire me by phone and word of mouth.\""), .direct("What were you doing the night of the incident?", "\"I was driving home from a late job for a customer. I drove through town on my way.\""), .direct("What do you say about the work order?", "\"It is in my phone. It shows a job for a customer's fence on the other side of town, scheduled that night.\""), .cross("Your truck was at both sites, wasn't it?", "\"So the surveillance says. I do not know how. I was working.\""), .cross("Matching cans of paint were in your truck, weren't they?", "\"I painted for a living. Cans are in my truck all the time.\""), .cross("A work order exists in your phone. Does it cover the mural?", "\"No. It is for another job. I can show it.\""), .cross("You owed the town a fine, didn't you?", "\"Yes, for a permit violation. I was angry about it, but I did not take it out on a mural.\""), .cross("You knew the town mural was on a wall you drove past that night, didn't you?", "\"I knew the mural was there. I drive past it a few times a week, but I did not stop and I did not touch it.\"")],
        openings: ("A town mural was painted over and a school wall sprayed, causing $8,400 in damage. Surveillance shows a truck registered to {D} at both sites, with matching paint cans in the truck.", "The defense witnesses will explain that {D} was hired to paint a different wall, that a work order exists, and that the truck was one of many in town."),
        closings: ("A truck at both sites, matching cans in the bed, and a fine owed to the town. The pieces point to {D}.", "A painter's truck carries paint all the time. The State has shown a truck, not a hand, and a work order places {D} elsewhere."),
        timeline: [(0, "Night: the mural."), (0, "Night: the school."), (1, "The town finds it."), (2, "{DL} is traced.")],
        identified: "Surveillance.",
        mood: .divided,
        doctrines: ["mistakeOfFact"])

    static let fountainDestroyed = SmallCases.make(
        key: "story.fountainDestroyed",
        category: .property,
        headlines: ["Teens Destroy Downtown Fountain With Crowbars", "Water Main Ruptured"],
        law: "injuryRealProperty",
        threshold: 7,
        spec: "Willfully and wantonly injured real property of {V}, a town, causing damage of $38,000, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Teens broke a downtown fountain with crowbars on {DATE}, rupturing a water main. {D} was identified from a video. {DL} says {D.he} only watched.",
        state: [E(.video, 3, "Square Camera", "Four teens with crowbars."), E(.physical, 3, "Crowbar", "A crowbar with {D}'s prints.", .search), E(.document, 2, "Repair Estimate", "$38,000.")],
        defense: [E(.statement, 1, "Watched", "{DL} says {D.he} only watched.")],
        role: "Town manager",
        exam: [.direct("What happened to the downtown fountain on {DATE}?", "\"Teens broke it with crowbars, rupturing a water main. The repair estimate is $38,000.\""), .direct("What does the square camera show?", "\"Four teens with crowbars. One of them was identified as {D}.\""), .direct("What was recovered?", "\"A crowbar with {D.his} fingerprints on it. It was found near the fountain.\""), .direct("What was the fountain?", "\"A stone fountain in the town square that had stood for eighty years, with a basin and a bronze statue. It sits above a water main that feeds the downtown.\""), .direct("How did you learn what happened?", "\"A street sweeper called me at six that a fountain was spraying water into the road. We shut off the main and found the basin broken apart.\""), .direct("Could you tell the teens apart on the video?", "\"Only one clearly, by the jacket. The others had hoods up and faced away from the lens.\""), .cross("{DL} says {D.he} only watched, doesn't {D.he}?", "\"I can't tell from the camera exactly what each teen did.\""), .cross("Are fingerprints proof of who swung?", "\"No. A print shows someone touched it. It doesn't tell me when or whether it was swung.\""), .cross("Can you see all four faces?", "\"Not all. The camera is at a distance. I rely on the identification of {DL}.\""), .cross("{D}'s fingerprints were on one crowbar, but that is all you have, isn't it?", "\"A fingerprint and the video. I cannot say from either who delivered the blows.\""), .cross("The video does not show every face clearly, does it?", "\"Not every one. Two faces are hooded and one turns away. We matched {D.him} through clothing and a distinctive jacket, and that is where the identification came from.\"")],
        defenseRole: "Late-night jogger",
        defenseExam: [.direct("What were you doing in the square that night?", "\"I was on a late jog around one in the morning, passing through the square on my usual route. I run it a few nights a week.\""), .direct("What did you see at the fountain?", "\"Four teens with long metal bars hitting the base of the fountain. I slowed down to look.\""), .direct("What was the fourth one doing?", "\"Standing a few feet back with arms at the sides. I did not see that one swing, as far as I could tell.\""), .direct("What did you do?", "\"I kept running and called the police from a block away. I told them what I had seen, but I was too far to see faces.\""), .direct("What did you hear?", "\"Metal on stone, then a crack and the sound of rushing water. Someone yelled to run.\""), .direct("How was the lighting?", "\"Dim, with a streetlight on the far side. I could make out shapes and movements but not clear faces.\""), .cross("You cannot say which teen was {D}, can you?", "\"I am fairly sure the one standing back was the one in the photo, but I would not swear to it.\""), .cross("You were a long way off, weren't you?", "\"About fifty yards. I was at the edge of the square.\""), .cross("You did not see the main burst happen, did you?", "\"I saw the water shooting up. I did not see which blow caused it.\""), .cross("The one holding the bar earlier might have swung too, couldn't have?", "\"It is possible. I only saw the end of it.\""), .cross("You called the police after you ran past, didn't you?", "\"Yes, a minute or so after, from the corner.\"")],
        theory: ("{D} wrecked a fountain.", "A bystander."),
        allocution: "\"I was with friends, and I watched them hit that fountain, and I'm ashamed that I stood there. I held a crowbar when it was passed around, but I never swung it at the fountain. I'm sorry for what it cost the town, and I'll help pay for the repair.\"",
        truths: ("{DL} held a crowbar in the video.", "{DL} stepped back before the break."),
        defendant: [.direct("Were you at the fountain that night?", "\"Yes. I was with friends. I watched them hit the fountain. I didn't swing.\""), .direct("Did you touch a crowbar?", "\"I handled one when it was passed around. I didn't use it on the fountain.\""), .direct("Why didn't you leave?", "\"I was frozen. I wasn't sure what to do. I should have walked away.\""), .direct("How did you get to the fountain?", "\"I was with three friends walking through the square after midnight. One of them had crowbars in a backpack, and I did not know why.\""), .direct("What did you do?", "\"I took a crowbar when it was handed to me and held it for a second. Then I stepped back and watched them swing.\""), .direct("What happened when the pipe burst?", "\"Water shot up and everyone ran. I ran too, and I did not call anyone.\""), .cross("You were there with the others, weren't you?", "\"Yes. I stood with them. That was wrong.\""), .cross("Your prints are on a crowbar, aren't they?", "\"Yes. I touched it. That doesn't mean I broke anything.\""), .cross("The fountain was destroyed, wasn't it?", "\"Yes. I'm sorry. I didn't think they would go that far.\""), .cross("Where did you put the crowbar down?", "\"On the ground near the base of the fountain. I didn't pick it up again.\""), .cross("You stayed until it was done, didn't you?", "\"I stayed through the swinging, and I did not tell them to stop.\"")],
        openings: ("Four teens with crowbars broke a downtown fountain and ruptured a water main, a $38,000 repair. {D} was identified from the camera, and a crowbar carries {D.his} prints. The State will show the video and the crowbar.", "Jurors will also see a jogger who saw three teens swinging and one standing back, and a teen who watched and did not swing. Listen closely to the witnesses."),
        closings: ("Four teens, crowbars, a burst main, and {D}'s prints on a crowbar. {D.He} took part in destroying a fountain that stood for eighty years, and stepping back at the end does not undo being there.", "A jogger saw one teen standing back. A print on a crowbar shows someone touched it, not who swung it, and the State has not proved {D} did any of the damage."),
        timeline: [(0, "1 a.m.: the crowbars."), (0, "1:10 a.m.: the break."), (0, "6 a.m.: the town notices."), (2, "Arrests.")],
        identified: "A video.",
        mood: .sympathetic,
        doctrines: ["lesserIncluded"])

    static let busSeatsSlashed = SmallCases.make(
        key: "story.busSeatsSlashed",
        category: .property,
        headlines: ["Students Slash Seats on Parked School Buses", "Knife Marks on Forty Seats"],
        law: "injuryPersonalProperty",
        threshold: 6,
        spec: "Willfully and wantonly injured personal property of {V}, a school district, causing damage of $11,000, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Seats on parked school buses were slashed on {DATE}. A depot camera showed three students; {D} was identified. {DL} says {D.he} only went along.",
        state: [E(.video, 3, "Depot Camera", "Three students on a bus."), E(.physical, 3, "Knife", "A knife in {D}'s locker.", .search), E(.document, 2, "Estimate", "$11,000.")],
        defense: [E(.statement, 1, "Along", "{DL} says {D.he} only went along.")],
        role: "Transportation supervisor",
        exam: [.direct("What did you find at the bus depot on {DATE}?", "\"Seats on parked school buses had been slashed. The damage estimate is $11,000.\""), .direct("What does the depot camera show?", "\"Three students on a bus. {D} was identified as one of them.\""), .direct("What was found afterward?", "\"A knife in {D.his} locker. It was found during a search.\""), .direct("What is the depot used for?", "\"We park about sixty school buses overnight in a fenced lot. A single camera covers the middle rows.\""), .direct("How was the damage discovered?", "\"A driver started a bus at five-thirty the next morning and noticed long cuts in the vinyl seats. We checked the others and found damage on six buses.\""), .direct("What did you do when you saw the damage?", "\"I called the district office and kept the buses out of service until a mechanic could check them. Six of them needed new seat covers before they could run.\""), .cross("{DL} says {D.he} only went along, doesn't {D.he}?", "\"I can't say who cut how many seats. The camera shows three on the bus.\""), .cross("Did you see {DL} cut a seat?", "\"I don't see the cutting in detail. The footage is limited.\""), .cross("Is a knife in a locker unusual?", "\"Not unusual for lunch, though a knife on school property is a concern. I can't say it was the one used.\""), .cross("You cannot see how many seats each student cut, can you?", "\"No. The footage is dark and from far away.\""), .cross("A pocket knife is common to carry, isn't it?", "\"Many students carry them for lunches. It is against school rules, but common.\"")],
        defenseRole: "Friend",
        defenseExam: [.direct("How do you know {D}?", "\"We are good friends and have been in the same classes for three years. We often hang out after school.\""), .direct("Were you at the depot that night?", "\"Yes. I was one of the three. I am not proud of that.\""), .direct("How did it start?", "\"One of the others had the idea and pushed us to do it. We all went along.\""), .direct("What did the defendant do on the bus?", "\"Cut a few seats, like the rest of us, then stopped. {D} looked uneasy.\""), .direct("How many seats did the defendant cut?", "\"Not many, maybe a few. I did not count, but it was far fewer than the total.\""), .direct("How did you feel when it was over?", "\"Sick. We ran off the lot and did not speak much.\""), .cross("You cut seats too, didn't you?", "\"Yes, I cut some. I do not want to put it all on {DF}.\""), .cross("Nobody stopped anyone, did they?", "\"No. We kept going until it was done.\""), .cross("You are a friend of the defendant, aren't you?", "\"Yes, and I want to be honest even though that hurts us both.\""), .cross("You cannot say exactly how many the defendant cut, can you?", "\"Not exactly. It was dark and we were all moving.\""), .cross("The damage totaled thousands of dollars, didn't it?", "\"I know. I did not think about that until later.\"")],
        theory: ("{D} slashed seats.", "Went along."),
        allocution: "\"I went along with two friends that night, and I didn't plan it. I wanted to fit in. I cut a couple of seats when the others did, and I'm ashamed of it. I'm sorry to the school district and to every kid who rides those buses. I'll help pay for the damage.\"",
        truths: ("{DL} cut twelve seats.", "The knife was a pocket knife used for lunch."),
        defendant: [.direct("Why were you on the bus?", "\"I went along with two friends. I didn't plan it. I wanted to fit in.\""), .direct("Did you cut seats?", "\"A few. I cut a couple when the others did. I'm ashamed of it.\""), .direct("Why did you have a knife?", "\"It was for ordinary use, like cutting things at lunch. I didn't plan to use it on buses.\""), .direct("How did you end up at the depot?", "\"Two friends said it would be a quick prank at the lot, and I tagged along. I did not know what they planned.\""), .direct("What did you do on the bus?", "\"I stood in the aisle at first, then took my pocket knife and made some cuts in a couple of seats. It felt like a joke until I saw the damage.\""), .direct("How did you feel afterward?", "\"Ashamed. I knew the buses were for kids and I knew the cost would be high.\""), .cross("How many seats were slashed in all?", "\"I don't know. A lot. I didn't count. I know the damage was bad.\""), .cross("You had a knife in your locker, didn't you?", "\"Yes. It was mine. I should not have had it at school.\""), .cross("You cut seats yourself, didn't you?", "\"Yes. I did, and I am not trying to hide behind the others.\""), .cross("You could have said no and left, couldn't you?", "\"Yes. I did not want to look like I was scared.\""), .cross("You carried the knife onto the bus yourself, didn't you?", "\"Yes, it was in my pocket from lunch. I did not mean to use it, but I did, and I cannot undo the damage to those seats.\"")],
        openings: ("Seats on parked school buses were slashed, an $11,000 loss, and a depot camera shows three students on a bus. {D} was identified, and a knife was found in {D.his} locker. The State will present the supervisor.", "The defense evidence includes a student who went along with friends, cut only a few seats, and has admitted it. Listen closely to the witnesses."),
        closings: ("Three students, slashed seats, $11,000 in damage, and a knife in {D}'s locker. {DL} was part of the group that destroyed those seats.", "{D} followed the group and cut only a few seats. The State has not proved {DL} cut all the damage, only that {D.he} was a follower."),
        timeline: [(0, "9 p.m.: the bus."), (0, "9:30 p.m.: the slashing."), (1, "The driver finds it."), (2, "{DL} is identified.")],
        identified: "A camera.",
        mood: .sympathetic,
        doctrines: ["lesserIncluded"])

    static let jailLockdownRiot = SmallCases.make(
        key: "story.jailLockdownRiot",
        category: .publicOrder,
        headlines: ["Inmates Riot at County Jail After Lockdown", "Fire Set in Dayroom"],
        law: "riot",
        threshold: 8,
        spec: "Participated in a riot with three or more persons causing property damage and injury, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Inmates broke fixtures and lit a fire in a dayroom on {DATE} after a lockdown. Three officers were hurt. {D} was filmed leading the break. {DL} says {D.he} was trying to calm others.",
        state: [E(.video, 3, "Dayroom Camera", "{D} breaks a fixture."), E(.statement, 3, "Officer", "'{D} led them.'"), E(.forensic, 2, "Medical Reports", "Three officers hurt.")],
        defense: [E(.statement, 1, "Calming", "{DL} says {D.he} was calming others.")],
        role: "Jail officer",
        exam: [.direct("What happened in the dayroom on {DATE}?", "\"After a lockdown, inmates broke fixtures and lit a fire. Three officers were hurt. It was chaotic and dangerous.\""), .direct("What were the injuries?", "\"Three officers were hurt. The medical reports document them, including bruises and cuts.\""), .direct("What led up to the disturbance?", "\"A lockdown at about six after a fight on another unit. Inmates in the dayroom were told to stay inside and some were frustrated about missing the evening phone time.\""), .direct("What did you see {D} do?", "\"{D} climbed on a table, shouted at the group, and swung a metal stool into a wall-mounted fixture. Others joined and started breaking the TV bracket and benches.\""), .direct("What did the group do next?", "\"About thirty minutes later someone lit a pile of papers under a table. The sprinklers kicked in, and we pulled officers back until backup arrived.\""), .direct("How did the unit respond once the fire was reported?", "\"We called a lockdown, cleared the dayroom, and sent a response team. The fire was put out, and the three injured officers went to the medical unit.\""), .cross("{DL} says {D.he} was calming others, doesn't {D.he}?", "\"I saw {DL} break a fixture. I can't say what {DL} did the whole time.\""), .cross("Did {DL} hurt an officer?", "\"I'm not aware that {DL} personally struck an officer. I know officers were hurt in the disturbance.\""), .cross("How many inmates were involved?", "\"Many. It was a large group. I can't say each one's role.\""), .cross("You did not see the defendant light the fire, did you?", "\"No. I saw the fire after it was started, and I did not see who set it.\""), .cross("Several inmates were shouting at once, weren't they?", "\"Yes, a lot of voices. I could not follow what each person said.\"")],
        defenseRole: "Fellow inmate",
        defenseExam: [.direct("Where were you that evening?", "\"In the dayroom with the rest of the unit. I was housed there and saw everything from my table.\""), .direct("What did you see {D} do?", "\"{D} broke a chair early on, then started yelling at others to calm down. {DF} grabbed one inmate and pulled that inmate away from an officer.\""), .direct("How did the other inmates react?", "\"Some listened and backed off, and some kept going. It got loud and hard to hear.\""), .direct("How did the officers react?", "\"They pulled back to the door and called for help. Some got hit by flying objects.\""), .direct("Who lit the fire?", "\"I did not see. It started under a table at the other end of the room.\""), .direct("What did you do?", "\"I stayed at my table and stayed out of it. I wanted no part of it.\""), .cross("{D} broke a chair before trying to calm anyone, didn't {D.he}?", "\"Yes. {D.He} was part of the early trouble.\""), .cross("You cannot say whether {D} led anyone, can you?", "\"I would not say led. I saw {DF} yelling, but I saw many others yelling too.\""), .cross("You are housed in that unit too, aren't you?", "\"Yes, and I have nothing to gain from this.\""), .cross("You did not see the whole thing, did you?", "\"Only the part in front of my table. The room is large.\""), .cross("The officers were hurt during the break, weren't they?", "\"Yes, at least three. I saw some of it happen.\"")],
        theory: ("{D} led a riot.", "Calming others."),
        allocution: "\"I broke a chair early on because I was angry about the lockdown, and then I tried to calm the others down. I never wanted anyone hurt, especially the officers. I'm sorry for what happened in that dayroom, and I want to serve my time quietly. I regret it.\"",
        truths: ("{DL} threw a chair.", "{DL} pulled one inmate away from an officer."),
        defendant: [.direct("What did you do during the disturbance?", "\"I tried to calm people down. I was trying to stop things from getting out of hand.\""), .direct("Did you break a fixture?", "\"Early on, I broke a chair. I was angry about the lockdown. Then I tried to calm others.\""), .direct("Did you light the fire?", "\"No. I didn't light anything. I never wanted anyone hurt.\""), .direct("How were things in the unit that week?", "\"Tense. We had been locked in for days over a fight on another unit, and a lot of us missed visits.\""), .direct("What happened that evening?", "\"I got angry about the lockdown and broke a chair against a table. Then it spread, and I could not stop it.\""), .direct("What did you do when the fire started?", "\"I tried to pull a friend back from an officer and shouted at people to stop. I did not light anything.\""), .cross("The camera shows you breaking a fixture, doesn't it?", "\"Yes. I did. I'm not denying it.\""), .cross("The officer says you led them, doesn't the officer?", "\"I didn't lead anyone. I was loud, and people may have followed.\""), .cross("You threw a chair, didn't you?", "\"Yes, I threw one. I was one of the first to break something.\""), .cross("Three officers were hurt, weren't they?", "\"I heard that afterward. I did not want anyone to be hurt, and I apologize.\""), .cross("You were angry about the lockdown when it began, weren't you?", "\"Yes, I was angry, like most of the unit. I had been told I would have a visit that week, and the lockdown canceled it.\"")],
        openings: ("After a lockdown, inmates broke fixtures and lit a fire in a jail dayroom, and three officers were hurt. The dayroom camera shows {D} breaking a fixture, and an officer says {DL} led them. The State will present the officer and the video.", "The defense will point you to an inmate who broke a chair out of anger and then tried to calm others, and who never lit the fire or hurt an officer."),
        closings: ("A camera shows {D} breaking a fixture in the riot, an officer says {DL} led, and three officers were hurt. {D.He} was part of the disturbance.", "{D} was angry, broke a chair, and then tried to calm others. The State has not proved {DL} led a riot or caused the injuries."),
        timeline: [(0, "6 p.m.: lockdown."), (0, "6:30 p.m.: the break."), (0, "7 p.m.: the fire."), (0, "8 p.m.: order restored.")],
        identified: "A jail camera.",
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let courthouseHallFight = SmallCases.make(
        key: "story.courthouseHallFight",
        category: .publicOrder,
        headlines: ["Families Brawl in Courthouse Hallway After Verdict", "Bailiffs Separate Two Groups"],
        law: "disorderly",
        threshold: 6,
        spec: "Disturbed the peace of the court by fighting, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Two families fought in a courthouse hallway on {DATE} after a verdict. {D} threw a punch caught on camera. {DL} says {D.he} was shoved first.",
        state: [E(.video, 3, "Hall Camera", "{D} punches."), E(.statement, 2, "Bailiff", "'The fight lasted a minute.'"), E(.forensic, 2, "Medical Note", "A split lip.")],
        defense: [E(.statement, 1, "Shoved", "{DL} says {D.he} was shoved first.")],
        role: "Bailiff",
        exam: [.direct("What happened in the courthouse hallway on {DATE}?", "\"Two families fought after a verdict. As bailiff, I saw the fight and the aftermath. It lasted about a minute.\""), .direct("What does the hallway camera show?", "\"It shows {D} throwing a punch. It's clear on the video.\""), .direct("Who was hurt?", "\"A split lip, according to the medical note. That person needed attention.\""), .direct("What happened right before the hallway fight?", "\"A verdict was read in a family dispute case, and the losing side stormed out. In the hallway two groups began shouting near the elevators.\""), .direct("Where were you stationed?", "\"At the end of the hallway by the courtroom doors. I heard the shouting and moved toward them.\""), .direct("What did you see when you reached them?", "\"Pushing and swinging among about eight people, and {DL} landing a punch on one of the other family members. I called for backup and began separating people.\""), .cross("{DL} says {D.he} was shoved first, doesn't {D.he}?", "\"I couldn't see every detail. Emotions were running high after the verdict.\""), .cross("Did you see the first contact?", "\"No. I came in after it started. I can't say who touched whom first.\""), .cross("Was it a mutual fight?", "\"It looked like it. Both families were involved, with shouting and shoving.\""), .cross("The hallway was crowded with people from both families, wasn't it?", "\"Yes, about eight people were in the group and others were coming out of courtrooms. It was crowded and loud.\""), .cross("Both families threw punches, didn't they?", "\"Yes. Several people on each side were involved before we cleared the hall.\"")],
        defenseRole: "Court clerk",
        defenseExam: [.direct("Were you in the hallway?", "\"Yes. I'm a court clerk. I was nearby when the fight began.\""), .direct("Who shoved first?", "\"I saw a shove. It came before any punches that I noticed.\""), .direct("What did you do?", "\"I stepped back and called for help. I'm not trained for fights.\""), .direct("What is your role?", "\"I work at the clerk's office, filing and handling case records. I was walking to the elevator with a file.\""), .direct("What did you see in the hallway?", "\"Two groups talking loudly, then a push. Someone in a gray jacket got shoved against the wall.\""), .direct("What happened next?", "\"A few punches, then bailiffs rushed in. I stepped back against the wall.\""), .cross("Who threw the shove?", "\"Unsure. I couldn't see who it was. People were close together.\""), .cross("Did you see {DL} punch?", "\"I saw a punch. I'm not certain who threw it.\""), .cross("Was {DL} shoved?", "\"Possibly. I saw a shove near {D}. I can't say it was aimed at {D.him}.\""), .cross("You cannot say who pushed first, can you?", "\"No. I only saw the push and the person who was shoved.\""), .cross("It was crowded where the punch was thrown, wasn't it?", "\"Yes. People were packed together, and I couldn't see every hand.\"")],
        theory: ("{D} fought in court.", "Shoved first."),
        allocution: "\"After that verdict, everyone was shouting, and I was shoved and surrounded. I threw a punch because I was scared. I didn't want to hurt anyone, and I regret it. I should never have fought in a courthouse hallway. I'll accept the court's judgment.\"",
        truths: ("{DL} threw the first punch.", "A bailiff saw a shove first."),
        defendant: [.direct("What started the fight?", "\"After the verdict, people were shouting. I was shoved. I threw a punch to protect myself.\""), .direct("Did you mean to hurt someone?", "\"No. I reacted. I was surrounded and scared. I didn't want to hurt anyone.\""), .direct("How do you feel now?", "\"Ashamed. It was a courthouse, and I should have walked away. I let emotions control me.\""), .direct("What was the case about?", "\"A property dispute with my relatives. The verdict went against us, and everyone was upset.\""), .direct("What happened in the hallway?", "\"Someone from the other side shoved me hard as we passed. I fell back against the wall and saw several people closing in.\""), .direct("Why did you throw a punch?", "\"I was scared and wanted them away from me. I swung without thinking.\""), .cross("The camera shows you punching, doesn't it?", "\"Yes. I threw a punch. I won't deny it.\""), .cross("You could have left the hallway, couldn't you?", "\"I could have. I was caught up in it. That's not an excuse.\""), .cross("Someone got a split lip, didn't they?", "\"Yes. I'm so sorry. I didn't intend that much harm.\""), .cross("You threw a punch at someone's face, didn't you?", "\"Yes, and it split their lip. I know I should have walked away.\""), .cross("You were at a courthouse and knew deputies were close, weren't you?", "\"I did not think about that until afterward.\"")],
        openings: ("After a verdict, two families fought in a courthouse hallway for about a minute. The hall camera shows {D} throwing a punch, and one person suffered a split lip.", "The defense will present a hallway where emotions boiled over, a clerk who saw a shove first, and a punch thrown in a moment of fear."),
        closings: ("A courthouse hallway, a verdict, and a punch on camera. {D} threw it, and someone went to the doctor with a split lip.", "A shove started it, and {D} responded in a crowd. The State has not proved {DL} started a fight or meant more than self-protection."),
        timeline: [(0, "3 p.m.: the verdict."), (0, "3:05 p.m.: the hall."), (0, "3:10 p.m.: bailiffs."), (0, "4 p.m.: arrest.")],
        identified: "A hall camera.",
        mood: .sympathetic,
        doctrines: ["selfDefense"])

    static let ambulanceEntryBlock = SmallCases.make(
        key: "story.ambulanceEntryBlock",
        category: .publicOrder,
        headlines: ["Protesters Block Hospital Ambulance Entrance", "Ambulance Delayed Eleven Minutes"],
        law: "disorderly",
        threshold: 6,
        spec: "Disturbed the peace by blocking an emergency vehicle entrance, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "Protesters blocked a hospital's ambulance entrance on {DATE}. An ambulance was delayed eleven minutes. {D} refused to move. {DL} says there was another entrance.",
        state: [E(.video, 3, "Hospital Camera", "{D} stands in the lane."), E(.document, 3, "Dispatch Log", "Eleven-minute delay."), E(.statement, 2, "Paramedic", "'I honked three times.'")],
        defense: [E(.statement, 1, "Other Entrance", "{DL} says there was another entrance.")],
        role: "Paramedic",
        exam: [.direct("What happened at the hospital on {DATE}?", "\"Protesters blocked the ambulance entrance. We were delayed eleven minutes. I honked three times.\""), .direct("What does the camera show?", "\"It shows {D} standing in the lane. {D.He} refused to move when we approached.\""), .direct("How did the delay matter?", "\"Eleven minutes with a patient on board is a long time. The dispatch log records the delay.\""), .direct("Where is the ambulance entrance and how is it used?", "\"It is a covered bay on the north side of the hospital, reserved for ambulances and marked with red lines and signs. Every emergency arrival goes through it.\""), .direct("What did you do when you reached the lane?", "\"We came up the ramp with a patient on a monitor and found people standing across both lanes. I honked three times and radioed dispatch.\""), .direct("Who was in the lane?", "\"About a dozen protesters with signs. {D.He} stood in the center with arms crossed and did not step aside when I honked.\""), .cross("{DL} says there was another entrance, doesn't {D.he}?", "\"There was another way in, but it was a longer route.\""), .cross("Did you try to get around {DL}?", "\"We looked at the options. Going around meant a longer trip with a patient.\""), .cross("Was the patient harmed by the delay?", "\"The patient was treated and did okay. But the delay was a risk, and I can't promise it never matters.\""), .cross("The patient was stable during the delay, wasn't the patient?", "\"Stable, yes, but we cannot always know that ahead of time. A change could have happened in those minutes.\""), .cross("The other entrance was marked with a sign, wasn't it?", "\"Yes, a sign on the road. It adds a half-mile detour through the parking structure, which is slow with a patient.\"")],
        defenseRole: "Protest organizer",
        defenseExam: [.direct("What was your role in the protest?", "\"I organized it, planned the signs, and filed the notice with the city. About fifteen people came.\""), .direct("Why was that location chosen?", "\"It has a lot of foot traffic and is close to the billing office. We wanted the hospital to see us.\""), .direct("What instructions did you give?", "\"To keep signs on the sidewalk and stay out of the driveway. I said to move if an ambulance came.\""), .direct("What did you see when the ambulance arrived?", "\"It came up fast and honked. Some people froze, and I rushed to get them to move.\""), .direct("Was there another way in?", "\"Yes. A second entrance around the corner is marked for ambulances. I thought it would be used if the main one was busy.\""), .direct("What did you do after?", "\"I apologized to the paramedics and told the group to leave the driveway. I did not want to hurt anyone.\""), .cross("You told people to stay out of the driveway, but some were in it, weren't they?", "\"Yes. People wandered, and I did not catch them all.\""), .cross("The delay was eleven minutes, wasn't it?", "\"The log says eleven, though it felt shorter to me in the moment.\""), .cross("{D} was told to move more than once, wasn't {D.he}?", "\"Yes. I asked at least twice before {D} stepped aside.\""), .cross("The other entrance was a longer route, wasn't it?", "\"Yes, I know that now. I did not know how much longer.\""), .cross("You were responsible for the group, weren't you?", "\"Yes. I own what happened.\"")],
        theory: ("{D} blocked an ambulance.", "A protest."),
        allocution: "\"I was protesting, and I believed we were blocking a nonessential entrance, and I didn't know it was an emergency until I heard the honking. There was another entrance for ambulances. I never wanted anyone to wait for care, and I regret the delay for that patient.\"",
        truths: ("{DL} was warned twice.", "A sign marked the other entrance."),
        defendant: [.direct("Why did you stand in the lane?", "\"I was protesting. I thought we were blocking a nonessential entrance. There was another entrance for ambulances.\""), .direct("Did you know an ambulance was coming?", "\"I didn't know until I heard the honking. I didn't realize it was an emergency.\""), .direct("Why did you refuse to move?", "\"I was caught in the moment. I thought the ambulance could use the other entrance. I didn't want to give up the protest.\""), .direct("What was the protest about?", "\"Hospital billing and charity care. We chose the entrance because staff and the news would see us.\""), .direct("What did you hear when the ambulance came?", "\"Honking and a siren. I thought it was another protester's noise until the driver got out and spoke to us.\""), .direct("What did you do then?", "\"I stepped to the side, told others to move, and the lane opened. It took a few minutes to clear.\""), .cross("The ambulance honked three times, didn't it?", "\"Yes. I heard it. I stayed because I thought there was another way.\""), .cross("You delayed a patient eleven minutes, didn't you?", "\"I understand that now. I didn't intend it. It was a bad decision.\""), .cross("The other entrance was a longer route, wasn't it?", "\"Yes. That's what I'm told. I didn't think about it.\""), .cross("You were warned to keep the lane clear, weren't you?", "\"Twice, by security. I did not take the warning seriously.\""), .cross("You stayed in the center of the lane, didn't you?", "\"Yes, and I did not understand that an emergency would use that lane.\"")],
        openings: ("Protesters blocked a hospital's ambulance entrance, and {D} refused to move from the lane. An ambulance was delayed eleven minutes after honking three times. The State will present the paramedic and the dispatch log.", "Jurors will also see a protest with another entrance available, and a protester who did not realize an emergency was waiting. Listen closely to the witnesses."),
        closings: ("An ambulance honked three times, {D} stood in the lane, and a patient waited eleven minutes at the door of a hospital. A protest does not need an ambulance bay.", "There was another entrance, and {D} did not understand that an emergency was waiting. The State must prove {DL} knew, and a protester who stepped aside on request is not a blockade."),
        timeline: [(0, "2 p.m.: the protest."), (0, "2:20 p.m.: the ambulance."), (0, "2:31 p.m.: the lane clears."), (0, "3 p.m.: arrest.")],
        identified: "A hospital camera.",
        mood: .divided,
        doctrines: ["relevance"])

    static let paramedicCashTheft = SmallCases.make(
